// window.storage only exists inside Claude artifacts — on a real deployed site it doesn't exist
// at all. This is a drop-in replacement with the exact same shape (get/set/delete, same return
// shape), backed by real browser localStorage, so every call site elsewhere in this file needed
// zero changes beyond swapping which object they call. Saves are personal-per-browser either way,
// same as window.storage always was — this isn't a downgrade, just the real-web equivalent.
const localSave = {
  async get(key) {
    const raw = localStorage.getItem(key);
    return raw === null ? null : { key, value: raw };
  },
  async set(key, value) {
    localStorage.setItem(key, value);
    return { key, value };
  },
  async delete(key) {
    localStorage.removeItem(key);
    return { key, deleted: true };
  },
};

// Synthesized sound effects via the Web Audio API — no external audio files, works everywhere.
// Browsers require a real user gesture before audio can play at all, so the AudioContext is
// created lazily on first actual play rather than at module load (which would silently do nothing).
let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    audioCtx = new AC();
  }
  if (audioCtx.state === 'suspended') audioCtx.resume();
  return audioCtx;
}
function playTone(ctx, freq, startTime, duration, { type = 'sine', gain = 0.1, glideTo = null } = {}) {
  const osc = ctx.createOscillator();
  const gainNode = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, startTime);
  if (glideTo) osc.frequency.exponentialRampToValueAtTime(glideTo, startTime + duration);
  gainNode.gain.setValueAtTime(0, startTime);
  gainNode.gain.linearRampToValueAtTime(gain, startTime + 0.012);
  gainNode.gain.exponentialRampToValueAtTime(0.001, startTime + duration);
  osc.connect(gainNode);
  gainNode.connect(ctx.destination);
  osc.start(startTime);
  osc.stop(startTime + duration + 0.03);
}
let soundEnabled = true; // synced from the Settings toggle via setSoundEnabled below
function setSoundEnabled(v) { soundEnabled = v; }
const sfx = {
  tap: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    playTone(ctx, 700, ctx.currentTime, 0.045, { type: 'sine', gain: 0.045 });
  },
  navigate: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    playTone(ctx, 440, ctx.currentTime, 0.06, { type: 'sine', gain: 0.04 });
  },
  questComplete: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    const t = ctx.currentTime;
    playTone(ctx, 523.25, t, 0.14, { type: 'triangle', gain: 0.09 });        // C5
    playTone(ctx, 659.25, t + 0.09, 0.18, { type: 'triangle', gain: 0.1 });  // E5
  },
  levelUp: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    const t = ctx.currentTime;
    [523.25, 659.25, 783.99, 1046.5].forEach((f, i) => { // C5 E5 G5 C6
      playTone(ctx, f, t + i * 0.08, 0.22, { type: 'triangle', gain: 0.1 });
    });
  },
  tierUnlock: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    const t = ctx.currentTime;
    [523.25, 659.25, 783.99, 1046.5, 1318.5].forEach((f, i) => {
      playTone(ctx, f, t + i * 0.07, 0.28, { type: 'triangle', gain: 0.11 });
    });
    playTone(ctx, 1567.98, t + 0.4, 0.5, { type: 'sine', gain: 0.06 }); // sparkle tail
  },
  locked: () => {
    if (!soundEnabled) return;
    const ctx = getAudioCtx(); if (!ctx) return;
    playTone(ctx, 180, ctx.currentTime, 0.16, { type: 'sine', gain: 0.07, glideTo: 130 });
  },
};

