function normalCDF(z) {
  const t = 1 / (1 + 0.2316419 * Math.abs(z));
  const d = 0.3989423 * Math.exp((-z * z) / 2);
  let p = d * t * (0.3193815 + t * (-0.3565638 + t * (1.781478 + t * (-1.821256 + t * 1.330274))));
  if (z > 0) p = 1 - p;
  return p;
}
const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));
const CONVERSIONS = {
  cooper: { toMetric: (v) => v * 1609.34, imperialUnit: 'mi' },
  sitreach: { toMetric: (v) => v * 2.54, imperialUnit: 'in' },
};
function toMetricValue(testKey, raw, units) { const conv = CONVERSIONS[testKey]; return conv && units === 'imperial' ? conv.toMetric(raw) : raw; }
function displayUnit(testKey, units) { const conv = CONVERSIONS[testKey]; return conv && units === 'imperial' ? conv.imperialUnit : NORMS[testKey].unit; }
function ageBandStats(sex, age, base) { const decades = Math.max(0, Math.floor((age - 25) / 10)); const decline = base.declinePerDecade || 0; const b = base[sex]; return { mean: b.mean - decline * decades, sd: b.sd }; }
function percentileFor(raw, { mean, sd }, direction = 'higher') { const z = direction === 'higher' ? (raw - mean) / sd : (mean - raw) / sd; return clamp(normalCDF(z) * 100, 0, 100); }

