function StrIcon({ size = 15, color = 'currentColor' }) { return <svg {...iconProps(size, color)}><path d="M -16,6 L -16,-9 Q -16,-14 -11,-14 L 11,-14 Q 16,-14 16,-9 L 16,6 Q 16,17 0,20 Q -16,17 -16,6 Z" /><path d="M -6,2 L 1,-6 L 5,0 L 10,-7" strokeWidth="2.2" /></svg>; }
