// Hand-drawn character avatar — deliberately a simple iconographic silhouette rather than a
// detailed face, matching the established "ember-lit silhouette, kept universal" direction for
// the player character (Section 9 of the art brief). Build/accent/accessory give real customization
// without needing generated art or compromising that universality.
const AVATAR_ACCENTS = { ember: colors.ember, teal: colors.teal, gold: colors.gold, moss: colors.moss };
const AVATAR_BUILDS = {
  lean: { shoulder: 24, waist: 15 },
  balanced: { shoulder: 30, waist: 20 },
  sturdy: { shoulder: 38, waist: 27 },
};
function KindledAvatar({ build = 'balanced', accent = 'ember', accessory = 'none', size = 120 }) {
  const accentColor = AVATAR_ACCENTS[accent] || colors.ember;
  const { shoulder, waist } = AVATAR_BUILDS[build] || AVATAR_BUILDS.balanced;
  return (
    <svg viewBox="-60 -75 120 150" width={size} height={size}>
      {/* legs */}
      <path d="M -9,28 L -11,58 M 9,28 L 11,58" stroke={colors.panelAlt} strokeWidth="11" strokeLinecap="round" fill="none" />
      {/* arms */}
      <path d={`M -${shoulder / 2},-6 L -${shoulder / 2 + 5},24 M ${shoulder / 2},-6 L ${shoulder / 2 + 5},24`} stroke={colors.panelAlt} strokeWidth="9" strokeLinecap="round" fill="none" />
      {/* torso */}
      <path d={`M -${shoulder / 2},-8 Q -${shoulder / 2 + 3},14 -${waist / 2},30 L ${waist / 2},30 Q ${shoulder / 2 + 3},14 ${shoulder / 2},-8 Z`} fill={colors.panelAlt} stroke={colors.border} strokeWidth="1.5" />
      {/* head */}
      <circle cx="0" cy="-28" r="15" fill={colors.panelAlt} stroke={colors.border} strokeWidth="1.5" />
      {/* ember/vigor core — the one constant across every build, echoing the Kindled's spark */}
      <circle cx="0" cy="8" r="9" fill={accentColor} opacity="0.9" />
      <circle cx="0" cy="8" r="15" fill={accentColor} opacity="0.22" />
      {accessory === 'hood' && <path d="M -19,-42 Q 0,-58 19,-42 L 18,-24 Q 0,-34 -18,-24 Z" fill={colors.bg} stroke={accentColor} strokeWidth="1.5" />}
      {accessory === 'staff' && <line x1="32" y1="-52" x2="32" y2="42" stroke={colors.textMuted} strokeWidth="4" strokeLinecap="round" />}
      {accessory === 'cloak' && <path d={`M -${shoulder / 2 + 2},-6 Q -${shoulder / 2 + 14},20 -${waist / 2 + 6},48 L ${waist / 2 + 6},48 Q ${shoulder / 2 + 14},20 ${shoulder / 2 + 2},-6 Z`} fill={colors.bg} opacity="0.75" stroke={accentColor} strokeWidth="1.2" />}
    </svg>
  );
}

