// Returns every perk effect currently unlocked for a class at a given level — Novice/Adept/Master
// tiers stack (reaching Master means Novice and Adept effects are still active too).
function activePerkEffects(className, level) {
  const cls = CLASS_DEFS.find((c) => c.name === className);
  if (!cls) return [];
  return TIERS.filter((t) => level >= t.level).map((t) => cls.perks[t.name].effect).filter(Boolean);
}
// Applies any active xpBonus effects matching this quest to its base XP value.
function xpWithPerkBonus(baseXp, quest, className, level) {
  const effects = activePerkEffects(className, level);
  let mult = 1;
  for (const eff of effects) {
    if (eff.type !== 'xpBonus') continue;
    const matches = eff.scope === 'all'
      || (eff.scope === 'boss' && (quest.type === 'boss' || quest.type === 'mini-boss'))
      || (eff.scope === 'side' && quest.type === 'side')
      || (Array.isArray(eff.scope) ? eff.scope.includes(quest.statFocus) : eff.scope === quest.statFocus);
    if (matches) mult += eff.pct / 100;
  }
  return Math.round(baseXp * mult);
}
// Applies any active restReduction effects matching the quest just completed.
function restHoursWithPerkReduction(hours, prevQuest, className, level) {
  const effects = activePerkEffects(className, level);
  let mult = 1;
  for (const eff of effects) {
    if (eff.type !== 'restReduction') continue;
    const matches = eff.scope === 'all'
      || (eff.scope === 'boss' && (prevQuest.type === 'boss' || prevQuest.type === 'mini-boss'))
      || eff.scope === prevQuest.statFocus;
    if (matches) mult -= eff.pct / 100;
  }
  return hours * Math.max(0.1, mult); // never reduce below 10% of the base window
}

function recommendClass(scores) {
  const ranked = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const top2 = ranked.slice(0, 2).map(([k]) => k);
  let best = null, bestOverlap = -1;
  for (const rule of CLASS_RULES) { const overlap = rule.stats.filter((s) => top2.includes(s)).length; if (overlap > bestOverlap) { bestOverlap = overlap; best = rule; } }
  return { name: best.name, basis: top2 };
}
const XP_PER_LEVEL = 160; // doubled from 80 — a single boss fight was granting 4+ levels in one completion, which read as too fast
const levelFromXP = (xp) => Math.floor(xp / XP_PER_LEVEL);
const xpForLevel = (lvl) => lvl * XP_PER_LEVEL;
const TIERS = [{ name: 'Novice', level: 4 }, { name: 'Adept', level: 13 }, { name: 'Master', level: 23 }]; // halved from 8/25/45 to match doubled XP_PER_LEVEL — same real XP thresholds (640/2080/3680 vs original 640/2000/3600), same unlock timing, just labeled with smaller numbers since each Level now represents twice the XP
const scaleRep = (base, mod, factor = 2, min = 3) => Math.max(min, Math.round(base + mod * factor));
const scaleSec = (base, mod, factor = 5, min = 10) => Math.max(min, Math.round(base + mod * factor));
const scaleMin = (base, mod, factor = 2, min = 10) => Math.max(min, Math.round(base + mod * factor));

