// Rest/recovery windows, grounded in standard exercise-science guidance: ~48h between
// vigorous resistance-type sessions, ~24h between vigorous cardio/agility sessions, mobility
// work is safe daily, and boss fights (a full Trials retest = near-maximal effort) need the
// longest recovery. A quest can override this default with its own `restHours` field.
const REST_HOURS_BY_TYPE = { story: 0, side: 0, main: 24, 'mini-boss': 48, boss: 72 };
function getRestHours(quest) {
  return quest.restHours !== undefined ? quest.restHours : REST_HOURS_BY_TYPE[quest.type];
}
// Real recovery is muscle-group/system-specific, not a single whole-body timer: back-to-back
// sessions hitting the SAME system (e.g. two STR quests in a row) need the full window, but a
// different system afterward (e.g. STR then CON) can reasonably go sooner. Boss fights and any
// "mixed" (full-body) quest always keep the full window regardless, since they load everything.
function effectiveRestHours(prevQuest, nextQuest) {
  const base = getRestHours(prevQuest);
  if (prevQuest.statFocus === 'mixed' || nextQuest.statFocus === 'mixed') return base;
  if (prevQuest.statFocus !== nextQuest.statFocus) return base * 0.5;
  return base;
}
function fmtRestRemaining(ms) {
  const totalMin = Math.ceil(ms / 60000);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  return h > 0 ? `${h}h ${m}m` : `${m}m`;
}

