const STAT_ICON_BY_KEY = { STR: StrIcon, CON: ConIcon, DEX: DexIcon, FLX: FlxIcon };
function dominantFocus(act) {
  const counts = {};
  act.chapters.flatMap((c) => c.quests).forEach((q) => {
    if (q.statFocus && q.statFocus !== 'mixed') counts[q.statFocus] = (counts[q.statFocus] || 0) + 1;
  });
  const entries = Object.entries(counts);
  if (!entries.length) return null;
  return entries.sort((a, b) => b[1] - a[1])[0][0];
}

const TYPE_LABEL = { story: 'Prologue', main: 'Main quest', side: 'Side quest', 'mini-boss': 'Mini-boss', boss: 'Boss fight' };
