/* ============================= MODAL ============================= */

function Modal({ title, onClose, children }) {
  useEffect(() => {
    const handleKey = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [onClose]);
  return (
    <div onClick={onClose} role="presentation" className="vf-modal-backdrop" style={{ position: 'fixed', inset: 0, background: 'rgba(10,9,7,0.72)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50, padding: 20 }}>
      <div onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" aria-label={title} className="vf-modal-dialog" style={{ borderRadius: 16, width: '100%', maxWidth: 440, maxHeight: '86vh', overflowY: 'auto', background: colors.bg, border: `1px solid ${colors.border}`, boxShadow: '0 24px 60px rgba(0,0,0,0.55)', padding: 22 }}>
        <div className="flex items-center justify-between" style={{ marginBottom: 14 }}>
          <div className="vf-display" style={{ fontSize: 19, color: colors.text }}>{title}</div>
          <button onClick={onClose} aria-label="Close" title="Close" style={{ borderRadius: 12, width: 36, height: 36, background: colors.panelAlt, border: `1px solid ${colors.border}`, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <X size={15} color={colors.textMuted} aria-hidden="true" />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

// --- Real Party backend (Supabase) ---
// Two tables: party_rooms (code -> room) and party_members (room_code -> each player's live stats).
// RLS policies on the Supabase side allow anyone holding a room code to read/write that room's
// data — the code itself is the access control, the same trust model as sharing a link. This is
// the anon/publishable key only; it can never do more than those policies allow, unlike a secret
// key, which is why it's safe to embed directly in client code like this.
// Vite exposes .env values through import.meta.env at build time, prefixed VITE_ so they're
// safe to ship client-side (Vite deliberately strips anything without that prefix from the
// build). Falls back to the values already in use so this still works with zero setup.
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || 'https://ssqdptddjbhzingrrdtj.supabase.co';
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY || 'sb_publishable_ykR9Mw9ouvahkoiezPDFxg_eqRfcLWq';
// The official SDK handles session persistence, token refresh, and OAuth redirects correctly —
// genuinely worth pulling in for auth specifically, rather than hand-rolling those edge cases
// the way the earlier raw-fetch approach was fine to do for simple Party reads/writes.
const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
async function supabaseFetch(path, options = {}) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...options,
    headers: {
      apikey: SUPABASE_ANON_KEY,
      Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
      'Content-Type': 'application/json',
      Prefer: 'return=representation',
      ...(options.headers || {}),
    },
  });
  const text = await res.text();
  if (!res.ok) {
    // Surface Supabase/PostgREST's actual error message (missing table, RLS rejection, bad key,
    // etc.) instead of swallowing it into a generic "request failed" — that detail is the
    // difference between a one-second diagnosis and guessing.
    let detail = text;
    try { detail = JSON.parse(text).message || text; } catch (e) { /* not JSON, use raw text */ }
    throw new Error(`(${res.status}) ${detail}`);
  }
  return text ? JSON.parse(text) : null;
}
function genRoomCode() {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no ambiguous 0/O/1/I
  let code = '';
  for (let i = 0; i < 5; i++) code += chars[Math.floor(Math.random() * chars.length)];
  return code;
}

const PARTY_GOAL = 1200;
function partyGoalMet(myXP, members) {
  const teammateTotal = members.reduce((sum, t) => sum + (t.xp || 0), 0);
  return teammateTotal + myXP >= PARTY_GOAL;
}

function PartyModal({ myXP, myLevel, characterName, roomCode, members, loading, error, onCreateRoom, onJoinRoom, onRefresh, onLeaveRoom }) {
  const [joinInput, setJoinInput] = useState('');
  const [copied, setCopied] = useState(false);
  const goal = PARTY_GOAL;
  const teammateTotal = members.reduce((sum, t) => sum + (t.xp || 0), 0);
  const combined = teammateTotal + myXP;
  const pct = clamp((combined / goal) * 100, 0, 100);
  const copyCode = () => {
    navigator.clipboard?.writeText(roomCode).catch(() => {});
    setCopied(true); setTimeout(() => setCopied(false), 1500);
  };

  // Not in a party yet — offer to create one or join an existing code
  if (!roomCode) {
    return (
      <div>
        <p className="vf-body" style={{ fontSize: 12.5, color: colors.textMuted, lineHeight: 1.5, marginBottom: 16 }}>
          Team up with real people. Create a party to get a code, or join one someone already shared with you — everyone's XP counts toward the same shared goal.
        </p>
        {error && (
          <div style={{ borderRadius: 12, background: 'rgba(189,74,38,0.15)', border: `1px solid ${colors.ember}`, padding: '8px 12px', marginBottom: 14 }}>
            <p className="vf-body" style={{ fontSize: 12, color: colors.text }}>{error}</p>
          </div>
        )}
        <button onClick={onCreateRoom} disabled={loading} className="vf-body vf-press"
          style={{ borderRadius: 12, width: '100%', padding: '12px 0', marginBottom: 14, background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', border: 'none', color: colors.text, fontSize: 14, fontWeight: 500, cursor: loading ? 'default' : 'pointer', opacity: loading ? 0.6 : 1 }}>
          {loading ? 'Working…' : 'Create a Party'}
        </button>
        <div className="flex items-center" style={{ gap: 8, marginBottom: 8 }}>
          <div style={{ flex: 1, height: 1, background: colors.border }} />
          <span className="vf-body" style={{ fontSize: 11, color: colors.textFaint }}>or</span>
          <div style={{ flex: 1, height: 1, background: colors.border }} />
        </div>
        <div className="flex" style={{ gap: 8 }}>
          <input value={joinInput} onChange={(e) => setJoinInput(e.target.value.toUpperCase())} placeholder="Enter party code"
            onKeyDown={(e) => e.key === 'Enter' && joinInput.trim() && onJoinRoom(joinInput.trim())}
            maxLength={8} className="vf-body" style={{ borderRadius: 12, flex: 1, background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '10px 12px', fontSize: 13, letterSpacing: 1 }} />
          <button onClick={() => joinInput.trim() && onJoinRoom(joinInput.trim())} disabled={loading || !joinInput.trim()} className="vf-body vf-press"
            style={{ borderRadius: 12, padding: '10px 16px', background: colors.panel, border: `1px solid ${colors.border}`, color: colors.text, fontSize: 13, cursor: loading ? 'default' : 'pointer', opacity: loading || !joinInput.trim() ? 0.6 : 1 }}>
            Join
          </button>
        </div>
      </div>
    );
  }

  // In a party — show real, live data
  return (
    <div>
      <p className="vf-body" style={{ fontSize: 12.5, color: colors.textMuted, lineHeight: 1.5, marginBottom: 14 }}>
        This week, the party's combined effort is needed to hold back a wandering threat. Every quest anyone completes adds to the shared total below — no one's individual pace is compared, only the party's total.
      </p>

      <div style={{ borderRadius: 12, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: '10px 14px', marginBottom: 14 }}>
        <div className="flex items-center justify-between">
          <div>
            <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint }}>Party code</div>
            <div className="vf-display" style={{ fontSize: 16, color: colors.gold, letterSpacing: 1 }}>{roomCode}</div>
          </div>
          <button onClick={copyCode} className="vf-body" style={{ borderRadius: 12, padding: '7px 12px', background: colors.panel, border: `1px solid ${colors.border}`, color: colors.text, fontSize: 12, cursor: 'pointer' }}>
            {copied ? 'Copied' : 'Copy'}
          </button>
        </div>
      </div>

      <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 14 }}>
        <div className="flex items-center justify-between vf-body" style={{ fontSize: 12, color: colors.textMuted, marginBottom: 6 }}>
          <span>Party goal this week</span><span style={{ color: colors.gold }}>{combined} / {goal} XP</span>
        </div>
        <div style={{ borderRadius: 999, height: 8, background: colors.borderSoft, overflow: 'hidden' }}>
          <div style={{ borderRadius: 999, height: '100%', width: `${pct}%`, background: 'linear-gradient(90deg, #D65A34, #B8923A)', transition: 'width 0.6s cubic-bezier(0.34, 1.2, 0.64, 1)' }} />
        </div>
      </div>

      <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 14 }}>
        <div className="flex items-center justify-between" style={{ marginBottom: 8 }}>
          <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint }}>Members</div>
          <button onClick={onRefresh} disabled={loading} className="vf-body" style={{ borderRadius: 8, background: 'transparent', border: 'none', color: colors.textFaint, fontSize: 11, cursor: 'pointer', textDecoration: 'underline' }}>
            {loading ? 'Refreshing…' : 'Refresh'}
          </button>
        </div>
        <div className="flex items-center justify-between vf-body" style={{ fontSize: 13, color: colors.text, padding: '5px 0' }}>
          <span>{characterName || 'You'}</span><span style={{ color: colors.textFaint }}>Lv {myLevel} · {myXP} XP</span>
        </div>
        {members.map((m) => (
          <div key={m.id} className="flex items-center justify-between vf-body" style={{ fontSize: 13, color: colors.text, padding: '5px 0' }}>
            <span>{m.character_name || 'Unnamed'}</span>
            <span style={{ color: colors.textFaint }}>Lv {m.level} · {m.xp} XP</span>
          </div>
        ))}
        {members.length === 0 && (
          <p className="vf-body" style={{ fontSize: 11.5, color: colors.textFaint, marginTop: 4 }}>No one else has joined yet — share the code above.</p>
        )}
      </div>

      <button onClick={onLeaveRoom} className="vf-body" style={{ borderRadius: 12, width: '100%', padding: '8px 0', background: 'transparent', border: `1px solid ${colors.border}`, color: colors.textFaint, fontSize: 12, cursor: 'pointer' }}>
        Leave Party
      </button>
    </div>
  );
}

function InventoryModal({ campaign, done }) {
  const earned = campaign.acts.flatMap((a) => a.chapters).flatMap((c) => c.quests).filter((q) => q.loot && done[q.id]);
  if (earned.length === 0) {
    return <p className="vf-body" style={{ fontSize: 13, color: colors.textFaint, textAlign: 'center', padding: '20px 0' }}>Nothing earned yet — complete a quest to start your inventory.</p>;
  }
  return (
    <div>
      {earned.map((q) => (
        <div key={q.id} className="flex items-start" style={{ gap: 10, padding: '10px 0', borderBottom: `1px solid ${colors.borderSoft}` }}>
          <Sparkles size={14} color={colors.gold} style={{ marginTop: 2, flexShrink: 0 }} />
          <div>
            <div className="vf-body" style={{ fontSize: 13, color: colors.text }}>{q.loot}</div>
            <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginTop: 1 }}>From: {q.title}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

function AuthModal({ onClose }) {
  const [mode, setMode] = useState('signin'); // 'signin' | 'signup'
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [username, setUsername] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [checkEmailSent, setCheckEmailSent] = useState(false);

  const handleGoogle = async () => {
    setError(null);
    await supabase.auth.signInWithOAuth({ provider: 'google', options: { redirectTo: window.location.origin } });
  };

  const handleSubmit = async () => {
    setError(null);
    if (!email.trim() || !password) { setError('Email and password are both required.'); return; }
    if (mode === 'signup' && !username.trim()) { setError('Pick a username — that\u2019s your identity in Party (and later, Guilds).'); return; }
    setLoading(true);
    try {
      if (mode === 'signup') {
        const { data, error: signUpError } = await supabase.auth.signUp({ email: email.trim(), password });
        if (signUpError) throw signUpError;
        if (data.user && !data.session) {
          setCheckEmailSent(true);
          setLoading(false);
          return;
        }
        if (data.user) {
          const { error: profileError } = await supabase.from('profiles').insert({ id: data.user.id, username: username.trim() });
          if (profileError) throw profileError;
        }
      } else {
        const { error: signInError } = await supabase.auth.signInWithPassword({ email: email.trim(), password });
        if (signInError) throw signInError;
      }
      onClose();
    } catch (e) {
      setError(e.message || 'Something went wrong. Please try again.');
    }
    setLoading(false);
  };

  if (checkEmailSent) {
    return (
      <div style={{ textAlign: 'center', padding: '10px 0' }}>
        <Mail size={28} color={colors.gold} style={{ marginBottom: 10 }} />
        <p className="vf-body" style={{ fontSize: 13, color: colors.text, lineHeight: 1.6 }}>
          Check <strong>{email}</strong> for a confirmation link. Once you click it, come back and sign in.
        </p>
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center" style={{ gap: 4, marginBottom: 16, background: colors.panelAlt, borderRadius: 12, padding: 3 }}>
        <button onClick={() => { setMode('signin'); setError(null); }} className="vf-body"
          style={{ borderRadius: 9, flex: 1, padding: '8px 0', background: mode === 'signin' ? colors.panel : 'transparent', border: 'none', color: mode === 'signin' ? colors.text : colors.textFaint, fontSize: 13, cursor: 'pointer' }}>
          Sign In
        </button>
        <button onClick={() => { setMode('signup'); setError(null); }} className="vf-body"
          style={{ borderRadius: 9, flex: 1, padding: '8px 0', background: mode === 'signup' ? colors.panel : 'transparent', border: 'none', color: mode === 'signup' ? colors.text : colors.textFaint, fontSize: 13, cursor: 'pointer' }}>
          Create Account
        </button>
      </div>

      {error && (
        <div style={{ borderRadius: 12, background: 'rgba(189,74,38,0.15)', border: `1px solid ${colors.ember}`, padding: '8px 12px', marginBottom: 14 }}>
          <p className="vf-body" style={{ fontSize: 12, color: colors.text }}>{error}</p>
        </div>
      )}

      {mode === 'signup' && (
        <input value={username} onChange={(e) => setUsername(e.target.value)} placeholder="Username — your identity in Party"
          className="vf-body" style={{ borderRadius: 12, width: '100%', background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '10px 12px', fontSize: 13, marginBottom: 10 }} />
      )}
      <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" type="email"
        className="vf-body" style={{ borderRadius: 12, width: '100%', background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '10px 12px', fontSize: 13, marginBottom: 10 }} />
      <input value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" type="password"
        onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
        className="vf-body" style={{ borderRadius: 12, width: '100%', background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '10px 12px', fontSize: 13, marginBottom: 14 }} />

      <button onClick={handleSubmit} disabled={loading} className="vf-body vf-press"
        style={{ borderRadius: 12, width: '100%', padding: '12px 0', marginBottom: 12, background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', border: 'none', color: colors.text, fontSize: 14, fontWeight: 500, cursor: loading ? 'default' : 'pointer', opacity: loading ? 0.6 : 1 }}>
        {loading ? 'Working…' : mode === 'signup' ? 'Create Account' : 'Sign In'}
      </button>

      <div className="flex items-center" style={{ gap: 8, marginBottom: 12 }}>
        <div style={{ flex: 1, height: 1, background: colors.border }} />
        <span className="vf-body" style={{ fontSize: 11, color: colors.textFaint }}>or</span>
        <div style={{ flex: 1, height: 1, background: colors.border }} />
      </div>

      <button onClick={handleGoogle} className="vf-body vf-press"
        style={{ borderRadius: 12, width: '100%', padding: '11px 0', background: colors.panel, border: `1px solid ${colors.border}`, color: colors.text, fontSize: 13.5, cursor: 'pointer' }}>
        Continue with Google
      </button>

      <p className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginTop: 14, lineHeight: 1.5 }}>
        Playing without an account still works — this only unlocks progress that follows you across devices, and a real identity in Party.
      </p>
    </div>
  );
}

function SettingsModal({ sex, setSex, age, setAge, units, setUnits, soundOn, setSoundOn, onResetProgress, onSwitchCampaign, campaignName, characterName, setCharacterName, avatarBuild, setAvatarBuild, avatarAccent, setAvatarAccent, avatarAccessory, setAvatarAccessory, profile, onOpenAuth, onSignOut }) {
  const [confirmingReset, setConfirmingReset] = useState(false);
  return (
    <div>
      <div style={{ marginBottom: 16, borderBottom: `1px solid ${colors.borderSoft}`, paddingBottom: 16 }}>
        <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 10 }}>Sound</div>
        <button onClick={() => setSoundOn(!soundOn)} className="vf-body flex items-center justify-between vf-press"
          style={{ borderRadius: 12, width: '100%', padding: '10px 14px', background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, fontSize: 13, cursor: 'pointer' }}>
          <span className="flex items-center" style={{ gap: 8 }}>
            {soundOn ? <Volume2 size={15} color={colors.gold} /> : <VolumeX size={15} color={colors.textFaint} />}
            Sound Effects
          </span>
          <span style={{ borderRadius: 999, width: 36, height: 20, background: soundOn ? colors.ember : colors.borderSoft, position: 'relative', transition: 'background 0.2s ease' }}>
            <span style={{ borderRadius: 999, width: 16, height: 16, background: colors.text, position: 'absolute', top: 2, left: soundOn ? 18 : 2, transition: 'left 0.2s ease' }} />
          </span>
        </button>
      </div>
      <div style={{ marginBottom: 16, borderBottom: `1px solid ${colors.borderSoft}`, paddingBottom: 16 }}>
        <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 6 }}>Account</div>
        {profile ? (
          <div>
            <div className="flex items-center" style={{ gap: 10, marginBottom: 10 }}>
              <div style={{ borderRadius: 999, width: 36, height: 36, background: colors.panelAlt, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                <User size={16} color={colors.gold} />
              </div>
              <div className="vf-body" style={{ fontSize: 13, color: colors.text }}>{profile.username}</div>
            </div>
            <p className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginBottom: 10, lineHeight: 1.5 }}>
              Progress follows this account across any device you sign in on. This is also your identity in Party.
            </p>
            <button onClick={onSignOut} className="vf-body flex items-center justify-center" style={{ borderRadius: 12, width: '100%', padding: '9px 0', gap: 6, background: 'transparent', border: `1px solid ${colors.border}`, color: colors.textFaint, fontSize: 12.5, cursor: 'pointer' }}>
              <LogOut size={13} /> Sign Out
            </button>
          </div>
        ) : (
          <div>
            <p className="vf-body" style={{ fontSize: 11.5, color: colors.textFaint, marginBottom: 10, lineHeight: 1.5 }}>
              Playing without an account — progress stays on this device only. Sign in to carry it across devices and get a real identity in Party.
            </p>
            <button onClick={onOpenAuth} className="vf-body vf-press" style={{ borderRadius: 12, width: '100%', padding: '10px 0', background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', border: 'none', color: colors.text, fontSize: 13, fontWeight: 500, cursor: 'pointer' }}>
              Sign In / Create Account
            </button>
          </div>
        )}
      </div>
      {campaignName && (
        <div style={{ marginBottom: 16, borderBottom: `1px solid ${colors.borderSoft}`, paddingBottom: 16 }}>
          <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 6 }}>Campaign</div>
          <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint, marginBottom: 8 }}>Currently playing: <span style={{ color: colors.text }}>{campaignName}</span></div>
          <button onClick={onSwitchCampaign} className="vf-body" style={{ borderRadius: 12, width: '100%', padding: '9px 0', background: 'transparent', border: `1px solid ${colors.border}`, color: colors.text, fontSize: 12.5, cursor: 'pointer' }}>
            Switch campaign
          </button>
        </div>
      )}
      {setCharacterName && (
        <div style={{ marginBottom: 16, borderBottom: `1px solid ${colors.borderSoft}`, paddingBottom: 16 }}>
          <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 10 }}>Character</div>
          <AvatarEditorFields name={characterName} setName={setCharacterName} build={avatarBuild} setBuild={setAvatarBuild} accent={avatarAccent} setAccent={setAvatarAccent} accessory={avatarAccessory} setAccessory={setAvatarAccessory} />
        </div>
      )}
      <div style={{ marginBottom: 16 }}>
        <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 6 }}>Sex &amp; Age</div>
        <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginBottom: 8 }}>Used to score your Trials against people your age and sex. Change here whenever it's out of date.</div>
        <div className="flex items-center" style={{ gap: 10 }}>
          <select value={sex} onChange={(e) => setSex(e.target.value)} style={{ borderRadius: 12, background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '6px 8px', fontSize: 13 }}>
            <option value="male">Male</option><option value="female">Female</option>
          </select>
          <input type="number" value={age} onChange={(e) => setAge(Number(e.target.value))} style={{ borderRadius: 12, width: 64, background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '6px 8px', fontSize: 13 }} />
        </div>
      </div>

      <div style={{ marginBottom: 16, borderTop: `1px solid ${colors.borderSoft}`, paddingTop: 16 }}>
        <div className="vf-body" style={{ fontSize: 13, color: colors.textMuted, marginBottom: 6 }}>Units</div>
        <div className="flex" style={{ borderRadius: 12, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: 3, gap: 3, width: 200 }}>
          {['imperial', 'metric'].map((u) => (
            <button key={u} onClick={() => setUnits(u)} className="vf-body"
              style={{ borderRadius: 12, flex: 1, padding: '7px 0', fontSize: 12, border: 'none', cursor: 'pointer', color: units === u ? colors.bg : colors.textMuted, background: units === u ? colors.text : 'transparent' }}>
              {u === 'imperial' ? 'Imperial' : 'Metric'}
            </button>
          ))}
        </div>
      </div>

      <div style={{ borderTop: `1px solid ${colors.borderSoft}`, paddingTop: 16 }}>
        <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginBottom: 8 }}>Testing tools — not a real feature</div>
        {!confirmingReset ? (
          <button onClick={() => setConfirmingReset(true)} className="vf-body"
            style={{ borderRadius: 12, width: '100%', padding: '10px 0', background: 'transparent', border: `1px solid ${colors.border}`, color: colors.textFaint, fontSize: 12.5, cursor: 'pointer' }}>
            Reset this campaign's progress
          </button>
        ) : (
          <div>
            <p className="vf-body" style={{ fontSize: 12, color: colors.gold, marginBottom: 8 }}>This clears every completed quest and stat in this campaign only — your other campaigns and account info are untouched. Are you sure?</p>
            <div className="flex" style={{ gap: 8 }}>
              <button onClick={() => { onResetProgress(); setConfirmingReset(false); }} className="vf-body vf-press"
                style={{ borderRadius: 12, flex: 1, padding: '9px 0', background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', border: 'none', color: colors.text, fontSize: 12.5, cursor: 'pointer' }}>
                Yes, reset
              </button>
              <button onClick={() => setConfirmingReset(false)} className="vf-body"
                style={{ borderRadius: 12, flex: 1, padding: '9px 0', background: 'transparent', border: `1px solid ${colors.border}`, color: colors.textMuted, fontSize: 12.5, cursor: 'pointer' }}>
                Cancel
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function PlaceholderModal({ label }) {
  return <p className="vf-body" style={{ fontSize: 13, color: colors.textFaint, textAlign: 'center', padding: '20px 0' }}>{label} is coming soon.</p>;
}

function DialogueStage({ dialogue, heroImage, onFinish, onSkip }) {
  const [i, setI] = useState(0);
  const beat = dialogue[i];
  const npc = NPCS[beat.npc] || NPCS.narrator;
  const isLast = i === dialogue.length - 1;
  // A quest-level heroImage (used for a region's arrival beat) takes priority over whichever
  // NPC happens to be speaking — the establishing shot of the region matters more in that one
  // moment than showing Senna's face again.
  const bgImage = heroImage || npc.portrait;
  return (
    <div>
      <div style={{ position: 'relative', margin: '-22px -22px 0', height: 360, overflow: 'hidden', background: colors.panelAlt }}>
        {bgImage && (
          <img src={bgImage} alt={heroImage ? 'Region' : npc.name} style={{ width: '100%', height: '100%', objectFit: 'cover', objectPosition: 'center top', display: 'block' }} />
        )}
        {bgImage && <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(rgba(13,12,10,0) 55%, rgba(13,12,10,0.5) 100%)' }} />}
        <button onClick={onSkip} className="vf-body" aria-label="Skip dialogue"
          style={{ borderRadius: 12, position: 'absolute', top: 12, right: 12, background: 'rgba(13,12,10,0.55)', border: `1px solid ${colors.border}`, color: colors.textMuted, fontSize: 11, padding: '5px 10px', cursor: 'pointer' }}>
          Skip
        </button>
      </div>
      {/* A real dialogue box, not just text over a gradient — a bordered panel with a raised
          name-plate tab overlapping its top edge, the classic tactics-RPG convention. */}
      <div style={{ position: 'relative', margin: '0 -22px', padding: '22px 22px 4px' }}>
        <div style={{ position: 'absolute', top: -14, left: 22, borderRadius: '8px 8px 0 0', background: npc.color || colors.ember, padding: '5px 16px 7px', boxShadow: '0 -2px 8px rgba(0,0,0,0.25)' }}>
          <div className="vf-display" style={{ fontSize: 14, color: colors.bg, fontWeight: 700 }}>{npc.name}</div>
        </div>
        <div style={{ borderRadius: '4px 12px 12px 12px', background: colors.panel, border: `1px solid ${colors.border}`, boxShadow: '0 8px 20px rgba(0,0,0,0.3)', padding: '18px 16px 14px' }}>
          <p className="vf-body" style={{ fontSize: 14, color: colors.text, lineHeight: 1.6, minHeight: 44 }}>{beat.line}</p>
        </div>
      </div>

      <div className="flex items-center justify-between" style={{ marginTop: 10, marginBottom: 10 }}>
        <div className="flex" style={{ gap: 4 }}>
          {dialogue.map((_, idx) => <div key={idx} style={{ width: 5, height: 5, borderRadius: '50%', background: idx === i ? colors.gold : colors.borderSoft }} />)}
        </div>
      </div>

      <button onClick={() => (isLast ? onFinish() : setI((n) => n + 1))} className="vf-body vf-press flex items-center justify-center"
        style={{ borderRadius: 12, width: '100%', padding: '13px 0', background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', color: colors.text, border: 'none', fontSize: 14, fontWeight: 500, cursor: 'pointer' }}>
        {isLast ? 'Begin Mission' : 'Continue'}
      </button>
    </div>
  );
}

const REQUIRED_TRIAL_TESTS = ['pushups', 'chairstand', 'cooper', 'plank', 'sidestep', 'balance', 'sitreach'];
function trialsDataComplete(raw) {
  return REQUIRED_TRIAL_TESTS.every((t) => raw[t] !== undefined && raw[t] !== '');
}
// Order of every Trials-gated quest through the story, used to check that a retest reflects
// data actually re-entered since the last one, not stale numbers from a previous Act.
function TrialsForm({ raw, setRaw, sex, age, units, seenTrialsTip, onDismissTrialsTip }) {
  return (
    <div>
      {!seenTrialsTip && (
        <OnboardingTip onDismiss={onDismissTrialsTip}>
          Enter your real results for each test below. Each one becomes a percentile against people your age and sex, then a score out of 20 and a modifier — that's what actually scales this quest's difficulty. Sex/age/units are set in Settings.
        </OnboardingTip>
      )}
      {STAT_DEFS.map((def) => {
        const Icon = def.icon;
        const results = def.tests.map((t) => {
          const norm = NORMS[t]; const bandStats = ageBandStats(sex, age, norm); const rawVal = raw[t];
          const metricVal = rawVal === '' || rawVal === undefined ? null : toMetricValue(t, rawVal, units);
          const pct = metricVal === null ? null : percentileFor(metricVal, bandStats, norm.direction);
          return { key: t, norm, pct };
        });
        const validPcts = results.filter((r) => r.pct !== null).map((r) => r.pct);
        const avgPct = validPcts.length ? validPcts.reduce((a, b) => a + b, 0) / validPcts.length : null;
        const score = avgPct !== null ? stat_score(avgPct) : null;
        const mod = score !== null ? modifier(score) : null;
        return (
          <div key={def.key} style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 12 }}>
            <div className="flex items-center justify-between" style={{ marginBottom: 8 }}>
              <div className="flex items-center" style={{ gap: 8 }}><Icon size={15} color={def.color} /><span className="vf-display" style={{ fontSize: 17, color: colors.text }}>{def.label}</span></div>
              <div className="vf-display" style={{ fontSize: 22, color: score !== null ? colors.text : colors.textFaint }}>{score !== null ? score : '–'}<span className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginLeft: 6 }}>{mod !== null ? fmtMod(mod) : ''}</span></div>
            </div>
            {results.map((r) => (
              <div key={r.key}>
                <label className="flex items-center justify-between vf-body" style={{ fontSize: 13, color: colors.textMuted, padding: '6px 0' }}>
                  <span>{r.norm.label}{r.norm.sourced ? '' : ' ·'}</span>
                  <span className="flex items-center" style={{ gap: 6 }}>
                    <input type="number" value={raw[r.key] === undefined ? '' : raw[r.key]} onChange={(e) => setRaw((prev) => ({ ...prev, [r.key]: e.target.value === '' ? '' : Number(e.target.value) }))}
                      style={{ borderRadius: 12, width: 64, background: colors.panelAlt, border: `1px solid ${colors.border}`, color: colors.text, padding: '4px 6px', fontSize: 13 }} />
                    <span style={{ color: colors.textFaint, width: 26 }}>{displayUnit(r.key, units)}</span>
                  </span>
                </label>
                {r.pct !== null && <div style={{ borderRadius: 999, height: 4, background: colors.borderSoft, marginBottom: 4, overflow: 'hidden' }}><div style={{ borderRadius: 999, height: '100%', width: `${r.pct}%`, background: def.color, transition: 'width 0.4s ease-out' }} /></div>}
              </div>
            ))}
            {def.tests.some((t) => !NORMS[t].sourced) && <div className="vf-body flex items-center" style={{ gap: 5, fontSize: 11, color: colors.textFaint, marginTop: 4 }}><Info size={11} /> · = provisional norm data</div>}
          </div>
        );
      })}
    </div>
  );
}

function TaskStage({ quest, done, onComplete, mods, raw, setRaw, sex, age, units, onOpenModal, seenQuestTip, onDismissQuestTip, seenTrialsTip, onDismissTrialsTip }) {
  const [mode, setMode] = useState('narrative');
  const isDone = !!done[quest.id];
  const blockedByTrials = quest.requiresTrials && !trialsDataComplete(raw) && !isDone;

  if (quest.requiresTrials) {
    if (isDone) {
      // Reviewing a completed Trials-gated quest: the live draft form (`raw`) belongs to
      // whatever Trials-gated quest is currently upcoming, not this one — showing it here would
      // either be empty or, worse, show someone else's in-progress numbers as if they were this
      // quest's historical result. This app only keeps the single most-recent committed snapshot
      // (Section 6 of the framework doc), not a per-quest history of raw inputs, so the honest
      // thing to show on review is a plain confirmation, not fabricated or borrowed numbers.
      return (
        <div>
          <div className="vf-body" style={{ fontSize: 11, color: TYPE_COLOR[quest.type], marginBottom: 10 }}>{TYPE_LABEL[quest.type]}</div>
          <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 14 }}>
            <p className="vf-body" style={{ fontSize: 13.5, color: colors.textMuted, lineHeight: 1.6 }}>{quest.narrativeText}</p>
          </div>
          <div className="vf-body" style={{ borderRadius: 12, fontSize: 12.5, color: colors.teal, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: '10px 12px', marginBottom: 14 }}>
            Trials completed. Open Character to see your current stats.
          </div>
          <button disabled className="vf-body flex items-center justify-center" style={{ borderRadius: 12, width: '100%', padding: '13px 0', background: colors.panelAlt, color: colors.textFaint, border: 'none', fontSize: 14, fontWeight: 500 }}>
            Completed
          </button>
        </div>
      );
    }
    return (
      <div>
        <div className="vf-body" style={{ fontSize: 11, color: TYPE_COLOR[quest.type], marginBottom: 10 }}>{TYPE_LABEL[quest.type]}</div>
        <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 14 }}>
          <p className="vf-body" style={{ fontSize: 13.5, color: colors.textMuted, lineHeight: 1.6 }}>{quest.narrativeText}</p>
        </div>
        <TrialsForm raw={raw} setRaw={setRaw} sex={sex} age={age} units={units} seenTrialsTip={seenTrialsTip} onDismissTrialsTip={onDismissTrialsTip} />
        <div className="flex items-center justify-between vf-body" style={{ fontSize: 12, color: colors.textFaint, marginBottom: 14 }}>
          <span>Reward</span><span style={{ color: colors.gold }}>{quest.xp} XP</span>
        </div>
        {blockedByTrials && (
          <div className="vf-body" style={{ borderRadius: 12, fontSize: 12, color: colors.gold, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: '8px 10px', marginBottom: 10 }}>
            Fill in every test above before completing this.
          </div>
        )}
        <button onClick={() => !isDone && !blockedByTrials && onComplete(quest.id)} disabled={isDone || blockedByTrials} className="vf-body flex items-center justify-center"
          style={{ borderRadius: 12, width: '100%', padding: '13px 0', background: isDone || blockedByTrials ? colors.panelAlt : colors.ember, color: isDone || blockedByTrials ? colors.textFaint : colors.text, border: 'none', fontSize: 14, fontWeight: 500, cursor: isDone || blockedByTrials ? 'default' : 'pointer' }}>
          {isDone ? 'Completed' : 'Mark complete'}
        </button>
      </div>
    );
  }

  return (
    <div>
      <div className="vf-body" style={{ fontSize: 11, color: TYPE_COLOR[quest.type], marginBottom: 10 }}>{TYPE_LABEL[quest.type]}</div>
      <div className="flex" style={{ borderRadius: 12, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: 3, gap: 3, marginBottom: 14, width: 200 }}>
        {['narrative', 'plain'].map((m) => (
          <button key={m} onClick={() => setMode(m)} className="vf-body"
            style={{ borderRadius: 12, padding: '5px 10px', fontSize: 11.5, border: 'none', cursor: 'pointer', color: mode === m ? colors.bg : colors.textMuted, background: mode === m ? colors.text : 'transparent' }}>
            {m === 'narrative' ? 'Narrative' : 'Plain'}
          </button>
        ))}
      </div>
      {!seenQuestTip && (
        <OnboardingTip onDismiss={onDismissQuestTip}>
          <strong>Narrative</strong> keeps you in the story. <strong>Plain</strong> shows the literal workout — sets, reps, and durations, scaled to your real stats. Switch anytime.
        </OnboardingTip>
      )}
      <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14, marginBottom: 14 }}>
        <p className="vf-body" style={{ fontSize: 13.5, color: colors.textMuted, lineHeight: 1.6 }}>{mode === 'narrative' ? quest.narrativeText : quest.plainText(mods)}</p>
      </div>
      <div className="flex items-center justify-between vf-body" style={{ fontSize: 12, color: colors.textFaint, marginBottom: 14 }}>
        <span>Reward</span><span style={{ color: colors.gold }}>{quest.xp} XP</span>
      </div>
      <button onClick={() => !isDone && onComplete(quest.id)} disabled={isDone} className="vf-body flex items-center justify-center"
        style={{ borderRadius: 12, width: '100%', padding: '13px 0', background: isDone ? colors.panelAlt : colors.ember, color: isDone ? colors.textFaint : colors.text, border: 'none', fontSize: 14, fontWeight: 500, cursor: isDone ? 'default' : 'pointer' }}>
        {isDone ? 'Completed' : quest.type === 'story' ? 'Continue' : 'Mark complete'}
      </button>
    </div>
  );
}

function QuestModal({ quest, chapterTitle, done, onComplete, mods, raw, setRaw, sex, age, units, onOpenModal, seenQuestTip, onDismissQuestTip, seenTrialsTip, onDismissTrialsTip }) {
  const isDone = !!done[quest.id];
  const hasDialogue = quest.dialogue && quest.dialogue.length > 0;
  const [stage, setStage] = useState(hasDialogue ? 'story' : 'task');
  return (
    <div>
      {stage === 'task' && quest.type === 'boss' && quest.bossImage && (
        <div style={{ borderRadius: 12, position: 'relative', margin: '-4px -4px 14px', overflow: 'hidden', border: `1px solid ${colors.border}` }}>
          <img src={quest.bossImage} alt={quest.title} style={{ width: '100%', display: 'block', maxHeight: 220, objectFit: 'cover' }} />
          <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(rgba(13,12,10,0), rgba(13,12,10,0.75))' }} />
          <div style={{ position: 'absolute', bottom: 8, left: 10, right: 10 }}>
            <span className="vf-display" style={{ fontSize: 14, color: colors.text, textShadow: '0 1px 4px rgba(0,0,0,0.8)' }}>{quest.title}</span>
          </div>
        </div>
      )}
      <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginBottom: 10 }}>{chapterTitle}</div>
      {stage === 'story'
        ? <DialogueStage dialogue={quest.dialogue} heroImage={quest.heroImage} onFinish={() => setStage('task')} onSkip={() => setStage('task')} />
        : <TaskStage quest={quest} done={done} onComplete={onComplete} mods={mods} raw={raw} setRaw={setRaw} sex={sex} age={age} units={units} onOpenModal={onOpenModal} seenQuestTip={seenQuestTip} onDismissQuestTip={onDismissQuestTip} seenTrialsTip={seenTrialsTip} onDismissTrialsTip={onDismissTrialsTip} />}
    </div>
  );
}

function ProgressChart({ statHistory }) {
  if (statHistory.length < 2) {
    return (
      <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 20, textAlign: 'center' }}>
        <p className="vf-body" style={{ fontSize: 13, color: colors.textFaint, lineHeight: 1.5 }}>
          Complete at least 2 Trials retests (your first Trials, plus any Act boss fight) to see your stats change over time.
        </p>
      </div>
    );
  }
  const data = statHistory.map((h, i) => ({ ...h, attempt: `#${i + 1}` }));
  return (
    <div style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${colors.border}`, padding: 14 }}>
      <div className="vf-body" style={{ fontSize: 12, color: colors.textMuted, marginBottom: 10 }}>Stat scores across every Trials retest — this is your real progress.</div>
      <ResponsiveContainer width="100%" height={220}>
        <LineChart data={data} margin={{ top: 5, right: 10, left: -20, bottom: 5 }}>
          <CartesianGrid stroke={colors.borderSoft} strokeDasharray="3 3" />
          <XAxis dataKey="attempt" tick={{ fill: colors.textFaint, fontSize: 10 }} />
          <YAxis domain={[0, 20]} tick={{ fill: colors.textFaint, fontSize: 10 }} />
          <Tooltip contentStyle={{ background: colors.panelAlt, border: `1px solid ${colors.border}`, fontSize: 12 }} labelStyle={{ color: colors.text }} />
          <Legend wrapperStyle={{ fontSize: 11 }} />
          <Line type="monotone" dataKey="STR" stroke={colors.ember} strokeWidth={2} dot={{ r: 3 }} />
          <Line type="monotone" dataKey="CON" stroke={colors.teal} strokeWidth={2} dot={{ r: 3 }} />
          <Line type="monotone" dataKey="DEX" stroke={colors.gold} strokeWidth={2} dot={{ r: 3 }} />
          <Line type="monotone" dataKey="FLX" stroke={colors.moss} strokeWidth={2} dot={{ r: 3 }} />
        </LineChart>
      </ResponsiveContainer>
      <div className="vf-body" style={{ fontSize: 10.5, color: colors.textFaint, marginTop: 6 }}>
        #1 = your initial Trials. Each # after that is an Act boss fight (a full Trials retest).
      </div>
    </div>
  );
}

function nextChapterPreview(campaign, done) {
  if (!campaign) return null;
  const allChapters = campaign.acts.flatMap((a) => a.chapters);
  const frontierChapterIndex = allChapters.findIndex((ch) => ch.quests.some((q) => !done[q.id]));
  if (frontierChapterIndex === -1 || frontierChapterIndex + 1 >= allChapters.length) return null;
  return allChapters[frontierChapterIndex + 1].storyBeat;
}
function SkillTreeView({ className, level, campaign, done }) {
  const cls = CLASS_DEFS.find((c) => c.name === className);
  return (
    <div>
      <div className="vf-body" style={{ fontSize: 11.5, color: colors.textFaint, marginBottom: 14, lineHeight: 1.5 }}>
        Tiers unlock by Level, not by stats — showing up consistently is what carries you deeper into the story, and the best perk stays out of reach until late.
      </div>
      {TIERS.map((t) => {
        const perk = cls.perks[t.name];
        const unlocked = level >= t.level;
        const preview = unlocked && perk.effect && perk.effect.type === 'storyPreview' ? nextChapterPreview(campaign, done) : null;
        return (
          <div key={t.name} style={{ borderRadius: 12, background: colors.panel, border: `1px solid ${unlocked ? colors.gold : colors.border}`, padding: 14, marginBottom: 12, opacity: unlocked ? 1 : 0.7 }}>
            <div className="flex items-center justify-between" style={{ marginBottom: 6 }}>
              <div className="flex items-center" style={{ gap: 8 }}>
                {unlocked ? <Sparkles size={14} color={colors.gold} /> : <Lock size={13} color={colors.textFaint} />}
                <span className="vf-display" style={{ fontSize: 15, color: unlocked ? colors.text : colors.textFaint }}>{t.name} — {perk.title}</span>
              </div>
              <span className="vf-body" style={{ fontSize: 11, color: unlocked ? colors.gold : colors.textFaint }}>Level {t.level}</span>
            </div>
            <p className="vf-body" style={{ fontSize: 12.5, color: unlocked ? colors.textMuted : colors.textFaint, lineHeight: 1.5 }}>{perk.desc}</p>
            {preview && (
              <div style={{ borderRadius: 10, background: colors.panelAlt, border: `1px solid ${colors.border}`, padding: 10, marginTop: 8 }}>
                <div className="vf-body" style={{ fontSize: 10, color: colors.gold, marginBottom: 3, textTransform: 'uppercase', letterSpacing: 0.5 }}>What's Ahead</div>
                <p className="vf-body" style={{ fontSize: 11.5, color: colors.textMuted, lineHeight: 1.5 }}>{preview}</p>
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

