function PathScreen({ campaign, done, level, className, xp, mods, onOpenQuest, onOpenModal, seenMenuTip, onDismissMenuTip, paywallUnlocked, onUnlockPaywall, partyMembers, characterName }) {
  // Re-render every minute so rest countdowns stay roughly live without excessive updates.
  const [, tick] = useState(0);
  useEffect(() => { const t = setInterval(() => tick((n) => n + 1), 60000); return () => clearInterval(t); }, []);

  // Level-up celebration: fires only on a real increase during this session, never on initial
  // mount/load (prevLevelRef starts at the current level, not at 0), so returning to an
  // already-leveled save doesn't replay the celebration every time the app opens. A regular
  // level-up gets a small toast; crossing an actual skill-tier threshold gets a bigger one that
  // names the perk just unlocked, since that's the moment that should feel like it actually matters.
  const [showLevelUp, setShowLevelUp] = useState(null); // null | { level, tierUnlocked: {name, title} | null }
  const prevLevelRef = useRef(level);
  useEffect(() => {
    if (level > prevLevelRef.current) {
      const crossedTier = TIERS.find((t) => prevLevelRef.current < t.level && t.level <= level);
      const cls = CLASS_DEFS.find((c) => c.name === className);
      const tierUnlocked = crossedTier && cls ? { name: crossedTier.name, title: cls.perks[crossedTier.name].title, desc: cls.perks[crossedTier.name].desc } : null;
      tierUnlocked ? sfx.tierUnlock() : sfx.levelUp();
      setShowLevelUp({ level, tierUnlocked });
      prevLevelRef.current = level;
      const t = setTimeout(() => setShowLevelUp(null), tierUnlocked ? 4500 : 3000);
      return () => clearTimeout(t);
    }
    prevLevelRef.current = level;
  }, [level, className]);

  const paywalledActIds = campaign.paywalledActIds;

  // Full campaign-wide quest sequence — rest windows and the frontier itself span across Acts,
  // even though only one Act's nodes get rendered at a time.
  const fullSequence = useMemo(() => campaign.acts.flatMap((act) =>
    act.chapters.flatMap((c) => c.quests.map((q) => ({ id: q.id, quest: q, chapterTitle: c.title, actId: act.id })))
  ), [campaign]);
  const frontierIndex = fullSequence.findIndex((q) => !done[q.id]);

  // Every quest the player could possibly complete right now, main-line AND branch variants for
  // their current class — used to find "what did I actually just do" for rest-gating, so a side
  // branch quest correctly counts as real effort the same as anything on the main line.
  const allQuestsForRest = useMemo(() => {
    const mainQuests = fullSequence.map((item) => item.quest);
    const branchQuests = campaign.acts.flatMap((act) => (act.branches || []).flatMap((b) => (b.questsByClass[className] || []).map((step) => step.quest)));
    return [...mainQuests, ...branchQuests];
  }, [fullSequence, campaign, className]);

  // Finds whichever completed quest most recently actually required real effort — skips 0-effort
  // story beats the same way the old array-position version did, just generalized to work across
  // branches too instead of only a fixed sequence position.
  const findLastRealEffortQuest = () => {
    let best = null, bestTime = -1;
    for (const q of allQuestsForRest) {
      if (q.type === 'story') continue;
      const t = done[q.id];
      if (t && t > bestTime) { bestTime = t; best = q; }
    }
    return best;
  };
  const computeResting = (nextQuest) => {
    if (nextQuest.type === 'story') return null;
    const prev = findLastRealEffortQuest();
    if (!prev) return null;
    const prevDoneAt = done[prev.id];
    const readyAt = prevDoneAt + restHoursWithPerkReduction(effectiveRestHours(prev, nextQuest), prev, className, level) * 3600 * 1000;
    const remaining = readyAt - Date.now();
    return remaining > 0 ? { remainingMs: remaining, prevQuestId: prev.id } : null;
  };

  let restingItem = null; // { id, remainingMs, prevQuestId }
  if (frontierIndex > 0) {
    const rest = computeResting(fullSequence[frontierIndex].quest);
    if (rest) restingItem = { id: fullSequence[frontierIndex].id, ...rest };
  }

  // Which Act the frontier quest currently sits in — this is "where the player is."
  const frontierActIndex = useMemo(() => {
    if (frontierIndex === -1) return campaign.acts.length - 1;
    const item = fullSequence[frontierIndex];
    return campaign.acts.findIndex((a) => a.id === item.actId);
  }, [frontierIndex, fullSequence, campaign]);

  // The Act currently on screen. Defaults to the frontier, but the player can browse back to
  // earlier (already-unlocked) Acts. Snaps to the frontier automatically whenever it advances —
  // that's the actual "finish an Act, arrive at the next map" moment.
  const [viewedActIndex, setViewedActIndex] = useState(frontierActIndex);
  useEffect(() => { setViewedActIndex(frontierActIndex); }, [frontierActIndex]);

  const viewedAct = campaign.acts[viewedActIndex];
  const actIsPaywalled = paywalledActIds.includes(viewedAct.id) && !paywallUnlocked;
  // When an Act has hand-placed coordinates matching its actual map art, nodes sit exactly on
  // the map's own visible road instead of a generic zigzag laid over a cropped background.
  const hasCustomLayout = !!viewedAct.nodePositions;
  const MAP_ASPECT = 700 / 544; // native aspect ratio of the generated region maps
  const MAP_ZOOM = 1.85; // render the map at 1.85x the viewport so it feels like a real, larger world, not a shrunk-to-fit icon
  // The visible "camera window" into the map now scales with the real device screen instead of
  // a small fixed box — accounts for the fixed top HUD, the header/Act-nav rows above it, and
  // the hint text + fixed bottom nav below it, with a floor so it never gets uncomfortably small
  // on short viewports. The full map can still be taller than this and pans/scrolls underneath.
  const VIEWPORT_HEIGHT = 'max(320px, calc(100dvh - 320px))';
  const fullMapWidth = Math.round(PATH_WIDTH * MAP_ZOOM);
  const fullMapHeight = Math.round(fullMapWidth / MAP_ASPECT);
  const imageDisplayHeight = Math.round(PATH_WIDTH / MAP_ASPECT); // used only by the legacy (non-custom-layout) fallback

  const actQuestItems = viewedAct.chapters.flatMap((c) => c.quests.map((q) => ({ id: q.id, quest: q, chapterTitle: c.title })));
  let y = PATH_TOP_PAD;
  let currentNodeId = null;
  const positioned = actQuestItems.map((item, idx) => {
    const globalIdx = fullSequence.findIndex((q) => q.id === item.id);
    let x, itemY;
    if (hasCustomLayout) {
      const pos = viewedAct.nodePositions[item.id];
      x = (pos.x / 100) * fullMapWidth;
      itemY = (pos.y / 100) * fullMapHeight;
    } else {
      x = nodeX(idx);
      itemY = y;
      y += NODE_SPACING;
    }
    const isDone = !!done[item.id];
    const isResting = restingItem && restingItem.id === item.id;
    const sequenceAvailable = frontierIndex === -1 ? true : globalIdx <= frontierIndex;
    const available = sequenceAvailable && !isDone && !isResting && !actIsPaywalled;
    if (available && currentNodeId === null) currentNodeId = item.id;
    return { ...item, x, y: itemY, isDone, isResting, available };
  });
  // Only reveal nodes actually reached so far — done, currently available, or resting. Anything
  // beyond the frontier stays hidden entirely rather than showing as a greyed-out locked node,
  // so the map unfolds as you actually explore it instead of spoiling the whole region up front.
  const visiblePositioned = positioned.filter((p) => p.isDone || p.available || p.isResting);

  // Branch quests: one map location per branch, but which actual quest lives there depends on
  // the player's current class — switching class before ever engaging a branch shows the new
  // class's version instead; once one variant is done, that branch stays done regardless of
  // later class changes, same as any other completed quest.
  const branchNodes = (viewedAct.branches || []).flatMap((branch) => {
    const steps = branch.questsByClass[className];
    if (!steps) return [];
    const nodes = [];
    let prevX = null, prevY = null;
    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];
      const afterCh = viewedAct.chapters.find((c) => c.id === step.afterChapter);
      const chapterReached = afterCh ? afterCh.quests.every((q) => !!done[q.id]) : false;
      const prevStepDone = i === 0 || !!done[steps[i - 1].quest.id];
      const reached = chapterReached && prevStepDone;
      const isDone = !!done[step.quest.id];
      const rest = (!isDone && reached) ? computeResting(step.quest) : null;
      const available = reached && !isDone && !rest && !actIsPaywalled;
      if (reached && (isDone || available || rest)) {
        let anchorX = null, anchorY = null, x, y;
        if (hasCustomLayout) {
          if (i > 0) {
            const prevPos = steps[i - 1].position;
            anchorX = (prevPos.x / 100) * fullMapWidth; anchorY = (prevPos.y / 100) * fullMapHeight;
          } else if (afterCh) {
            const anchorQuest = afterCh.quests[afterCh.quests.length - 1];
            const anchorPos = viewedAct.nodePositions[anchorQuest.id];
            if (anchorPos) { anchorX = (anchorPos.x / 100) * fullMapWidth; anchorY = (anchorPos.y / 100) * fullMapHeight; }
          }
          x = (step.position.x / 100) * fullMapWidth; y = (step.position.y / 100) * fullMapHeight;
        } else {
          // Legacy zigzag layout (no hand-placed art yet, e.g. The Long Road): compute the
          // anchor's position with the same formula the main path itself uses, then offset the
          // branch node to whichever side of center has more room, so it clears the zigzag's
          // full swing regardless of which phase the anchor happens to land on.
          if (i > 0) {
            anchorX = prevX; anchorY = prevY;
          } else if (afterCh) {
            const anchorQuest = afterCh.quests[afterCh.quests.length - 1];
            const anchorIdx = actQuestItems.findIndex((q) => q.id === anchorQuest.id);
            if (anchorIdx !== -1) { anchorX = nodeX(anchorIdx); anchorY = PATH_TOP_PAD + anchorIdx * NODE_SPACING; }
          }
          if (anchorX !== null) {
            const side = anchorX < PATH_WIDTH / 2 ? 1 : -1;
            x = anchorX + side * 85; y = anchorY + 55;
          }
        }
        if (x !== undefined) {
          prevX = x; prevY = y;
          nodes.push({
            id: step.quest.id, quest: step.quest, chapterTitle: `${viewedAct.name} — Side Path`,
            x, y, anchorX, anchorY, isDone, isResting: !!rest, available, restRemainingMs: rest ? rest.remainingMs : null,
          });
        }
      }
      if (!isDone) break; // don't reveal further steps in this chain until this one is actually done
    }
    return nodes;
  });
  const isActComplete = actQuestItems.every((q) => !!done[q.id]);
  const isLastAct = viewedActIndex === campaign.acts.length - 1;
  const showEnding = isLastAct && isActComplete && !hasCustomLayout; // custom-layout Acts don't currently include the campaign finale
  if (showEnding) y += DIVIDER_HEIGHT;
  const svgHeight = hasCustomLayout ? fullMapHeight : Math.max(y + 40, 480);
  const svgWidth = hasCustomLayout ? fullMapWidth : PATH_WIDTH;
  const containerHeight = hasCustomLayout ? VIEWPORT_HEIGHT : 480;

  const scrollRef = useRef(null);
  const currentRef = useRef(null);
  const [showPaywallPrompt, setShowPaywallPrompt] = useState(false);
  useEffect(() => {
    if (currentRef.current && scrollRef.current) {
      currentRef.current.scrollIntoView({ behavior: 'smooth', block: 'center', inline: 'center' });
    }
  }, [currentNodeId, viewedActIndex]);

  const linePath = visiblePositioned.map((n, i) => `${i === 0 ? 'M' : 'L'} ${n.x},${n.y}`).join(' ');
  const canGoPrev = viewedActIndex > 0;
  const canGoNext = viewedActIndex < frontierActIndex;

  return (
    <div style={{ position: 'relative' }}>
      <div style={{ height: 54 }} />
      <div style={{ position: 'fixed', top: 0, left: '50%', transform: 'translateX(-50%)', width: '100%', maxWidth: 560, padding: '10px 14px', paddingTop: 'calc(10px + env(safe-area-inset-top))', background: 'linear-gradient(180deg, rgba(13,12,10,0.98), rgba(13,12,10,0.85) 80%, rgba(13,12,10,0))', zIndex: 40, display: 'flex', alignItems: 'center', gap: 10, pointerEvents: 'none' }}>
        <div style={{ borderRadius: '50%', width: 40, height: 40, background: colors.panel, border: `2px solid ${colors.gold}`, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, boxShadow: '0 2px 8px rgba(0,0,0,0.4)' }}>
          <span className="vf-display" style={{ fontSize: 15, color: colors.gold }}>{level}</span>
        </div>
        <div style={{ flex: 1 }}>
          <div style={{ borderRadius: 999, height: 9, background: colors.borderSoft, overflow: 'hidden', border: `1px solid ${colors.border}` }}>
            <div style={{ borderRadius: 999, height: '100%', width: `${((xp % XP_PER_LEVEL) / XP_PER_LEVEL) * 100}%`, background: 'linear-gradient(90deg, #D65A34, #B8923A)', transition: 'width 0.5s ease' }} />
          </div>
        </div>
      </div>
      {showLevelUp && (
        <div className="vf-level-up-toast" style={{ position: 'absolute', top: 50, left: '50%', zIndex: 100, textAlign: 'center', pointerEvents: 'none', width: 280 }}>
          {showLevelUp.tierUnlocked ? (
            <div style={{ borderRadius: 16, background: 'linear-gradient(135deg, #D9A94A, #8A6A1E)', boxShadow: '0 14px 36px rgba(184,146,58,0.5)', padding: '14px 20px', border: '1px solid rgba(255,255,255,0.25)' }}>
              <div className="vf-body" style={{ fontSize: 10, color: 'rgba(255,255,255,0.9)', letterSpacing: 1, textTransform: 'uppercase', marginBottom: 3 }}>{showLevelUp.tierUnlocked.name} Tier Unlocked · Level {showLevelUp.level}</div>
              <div className="vf-display" style={{ fontSize: 19, color: '#fff', marginBottom: 3 }}>{showLevelUp.tierUnlocked.title}</div>
              <div className="vf-body" style={{ fontSize: 11, color: 'rgba(255,255,255,0.92)', lineHeight: 1.4 }}>{showLevelUp.tierUnlocked.desc}</div>
            </div>
          ) : (
            <div style={{ borderRadius: 16, background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 12px 32px rgba(189,74,38,0.45)', padding: '12px 24px', display: 'inline-block' }}>
              <div className="vf-body" style={{ fontSize: 10, color: 'rgba(255,255,255,0.85)', letterSpacing: 1, textTransform: 'uppercase', marginBottom: 2 }}>Level Up</div>
              <div className="vf-display" style={{ fontSize: 22, color: '#fff' }}>Level {showLevelUp.level}</div>
            </div>
          )}
        </div>
      )}
      <div className="flex items-center justify-between" style={{ marginBottom: 10 }}>
        <div>
          <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint }}>{characterName ? `${characterName} · ` : ''}Level {level} {className}</div>
          <div className="vf-display" style={{ fontSize: 20, color: colors.text }}>{campaign.name}</div>
        </div>
        {partyGoalMet(xp, partyMembers) && (
          <button onClick={() => onOpenModal('party')} aria-label="Party goal met — open Party" title="Party goal met"
            className="vf-press" style={{ borderRadius: 999, width: 34, height: 34, background: colors.panelAlt, border: `1px solid ${colors.ember}`, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <Users size={14} color={colors.ember} aria-hidden="true" />
          </button>
        )}
      </div>

      {!seenMenuTip && (
        <OnboardingTip onDismiss={onDismissMenuTip}>
          These four icons open your Character, Party, Inventory, and Settings — always one tap away, no matter where you are on the path.
        </OnboardingTip>
      )}

      <div className="flex items-center justify-between" style={{ marginBottom: 8 }}>
        <button onClick={() => canGoPrev && (setViewedActIndex((i) => i - 1), sfx.navigate())} disabled={!canGoPrev} aria-label="Previous Act"
          style={{ borderRadius: 12, background: 'transparent', border: 'none', color: canGoPrev ? colors.text : colors.borderSoft, cursor: canGoPrev ? 'pointer' : 'default', padding: 4, display: 'flex' }}>
          <ChevronLeft size={18} />
        </button>
        <div className="flex items-center vf-body" style={{ gap: 5, fontSize: 12, color: colors.gold }}>
          {(() => { const fk = dominantFocus(viewedAct); const FocusIcon = fk ? STAT_ICON_BY_KEY[fk] : null; return FocusIcon ? <FocusIcon size={13} color={colors.gold} /> : null; })()}
          Act {viewedAct.roman} — {viewedAct.name}
        </div>
        <button onClick={() => canGoNext && (setViewedActIndex((i) => i + 1), sfx.navigate())} disabled={!canGoNext} aria-label="Next Act"
          style={{ borderRadius: 12, background: 'transparent', border: 'none', color: canGoNext ? colors.text : colors.borderSoft, cursor: canGoNext ? 'pointer' : 'default', padding: 4, display: 'flex', transform: 'scaleX(-1)' }}>
          <ChevronLeft size={18} />
        </button>
      </div>

      <div ref={scrollRef} style={{
        height: containerHeight, overflow: 'auto', borderTop: `1px solid ${colors.border}`, borderBottom: `1px solid ${colors.border}`, backgroundColor: colors.panel, margin: '0 -22px', width: 'calc(100% + 44px)',
      }}>
        {actIsPaywalled ? (
          <div style={{ padding: '40px 20px', textAlign: 'center' }}>
            <Lock size={22} color={colors.gold} style={{ margin: '0 auto 10px' }} />
            <p className="vf-body" style={{ fontSize: 12.5, color: colors.text, lineHeight: 1.6, marginBottom: 12 }}>
              {viewedAct.name} is part of the full campaign. The first 3 Acts stay free forever.
            </p>
            <button onClick={onUnlockPaywall} className="vf-body" style={{ borderRadius: 12, padding: '9px 16px', background: colors.gold, border: 'none', color: colors.bg, fontSize: 12.5, fontWeight: 500, cursor: 'pointer' }}>
              Unlock full campaign (demo)
            </button>
          </div>
        ) : (
          <svg viewBox={`0 0 ${svgWidth} ${svgHeight}`} style={{ display: 'block', width: '100%', height: 'auto' }}>
            {hasCustomLayout && (
              <>
                <image href={viewedAct.mapImageUrl} x="0" y="0" width={fullMapWidth} height={fullMapHeight} preserveAspectRatio="xMidYMid slice" aria-hidden="true" />
                <rect x="0" y="0" width={fullMapWidth} height={fullMapHeight} fill="rgba(13,12,10,0.28)" />
              </>
            )}
            <path d={linePath} fill="none" stroke={colors.text} strokeWidth="3" strokeDasharray="2 9" strokeLinecap="round" opacity="0.6" />
            {visiblePositioned.map((item) => {
              const isCurrent = item.id === currentNodeId;
              const radius = item.quest.type === 'boss' ? 22 : item.quest.type === 'mini-boss' ? 19 : 16;
              const fill = item.isDone ? colors.teal : item.isResting ? colors.panelAlt : item.available ? colors.panel : colors.panelAlt;
              const stroke = item.isDone ? colors.teal : item.isResting ? colors.gold : isCurrent ? colors.ember : item.available ? colors.border : colors.borderSoft;
              const interactive = item.available || item.isDone;
              const activate = () => interactive ? onOpenQuest(item.id, item.chapterTitle) : item.isResting && sfx.locked();
              const stateLabel = item.isDone ? 'completed, tap to review' : item.isResting ? 'resting' : item.available ? 'available' : 'locked';
              return (
                <g key={item.id} ref={isCurrent ? currentRef : null} className="vf-node-in" style={{ cursor: interactive ? 'pointer' : 'default' }}
                  onClick={activate} tabIndex={interactive ? 0 : -1} role={interactive ? 'button' : undefined}
                  aria-label={interactive ? `${item.quest.title}, ${TYPE_LABEL[item.quest.type]}, ${stateLabel}` : undefined}
                  onKeyDown={(e) => { if (interactive && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); activate(); } }}>
                  {isCurrent && <circle cx={item.x} cy={item.y} r={radius + 7} fill="none" stroke={colors.ember} strokeWidth="1.5" opacity="0.5" className="vf-pulse" />}
                  <circle cx={item.x} cy={item.y} r={radius} fill={fill} stroke={stroke} strokeWidth="2.5" />
                  {item.isDone
                    ? <Check x={item.x - 7} y={item.y - 7} size={14} color={colors.bg} />
                    : item.isResting
                      ? <Clock x={item.x - 7} y={item.y - 7} size={14} color={colors.gold} />
                      : !item.available
                        ? <Lock x={item.x - 6} y={item.y - 6} size={12} color={colors.textFaint} />
                        : item.quest.type === 'boss'
                          ? <Swords x={item.x - 8} y={item.y - 8} size={16} color={colors.ember} />
                          : item.quest.type === 'mini-boss'
                            ? <Shield x={item.x - 7} y={item.y - 7} size={14} color={colors.teal} />
                            : <circle cx={item.x} cy={item.y} r="4" fill={TYPE_COLOR[item.quest.type]} />}
                  <text x={item.x} y={item.y + radius + 15} textAnchor="middle" fontSize="10" fill={item.available ? colors.text : item.isResting ? colors.gold : colors.textFaint} fontFamily="'Work Sans', sans-serif" style={{ paintOrder: 'stroke', stroke: colors.bg, strokeWidth: 3 }}>
                    {item.quest.title.length > 20 ? item.quest.title.slice(0, 18) + '…' : item.quest.title}
                  </text>
                  {item.isResting && (
                    <text x={item.x} y={item.y + radius + 28} textAnchor="middle" fontSize="9" fill={colors.textFaint} fontFamily="'Work Sans', sans-serif" style={{ paintOrder: 'stroke', stroke: colors.bg, strokeWidth: 3 }}>
                      resting — {fmtRestRemaining(restingItem.remainingMs)}
                    </text>
                  )}
                </g>
              );
            })}
            {branchNodes.map((item) => {
              const radius = 15;
              const fill = item.isDone ? colors.teal : item.isResting ? colors.panelAlt : item.available ? colors.panel : colors.panelAlt;
              const stroke = item.isDone ? colors.teal : item.isResting ? colors.gold : item.available ? colors.moss : colors.borderSoft;
              const interactive = item.available || item.isDone;
              const activate = () => interactive ? onOpenQuest(item.id, item.chapterTitle) : item.isResting && sfx.locked();
              const stateLabel = item.isDone ? 'completed side quest, tap to review' : item.isResting ? 'resting' : item.available ? 'available side quest' : 'locked';
              return (
                <g key={item.id}>
                  {item.anchorX !== null && (
                    <path d={`M ${item.anchorX},${item.anchorY} L ${item.x},${item.y}`} fill="none" stroke={colors.moss} strokeWidth="2.5" strokeDasharray="4 3" strokeLinecap="round" opacity="0.85" />
                  )}
                  <g className="vf-node-in" style={{ cursor: interactive ? 'pointer' : 'default' }}
                    onClick={activate} tabIndex={interactive ? 0 : -1} role={interactive ? 'button' : undefined}
                    aria-label={interactive ? `Side quest: ${item.quest.title}, ${stateLabel}` : undefined}
                    onKeyDown={(e) => { if (interactive && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); activate(); } }}>
                    <circle cx={item.x} cy={item.y} r={radius} fill={fill} stroke={stroke} strokeWidth="2.5" strokeDasharray="3 2" />
                    {item.isDone
                      ? <Check x={item.x - 6} y={item.y - 6} size={12} color={colors.bg} />
                      : item.isResting
                        ? <Clock x={item.x - 6} y={item.y - 6} size={12} color={colors.gold} />
                        : !item.available
                          ? <Lock x={item.x - 5} y={item.y - 5} size={10} color={colors.textFaint} />
                          : <circle cx={item.x} cy={item.y} r="3.5" fill={colors.moss} />}
                    <text x={item.x} y={item.y + radius + 13} textAnchor="middle" fontSize="9.5" fill={item.available ? colors.moss : item.isResting ? colors.gold : colors.textFaint} fontFamily="'Work Sans', sans-serif" style={{ paintOrder: 'stroke', stroke: colors.bg, strokeWidth: 3 }}>
                      {item.quest.title.length > 18 ? item.quest.title.slice(0, 16) + '…' : item.quest.title} ✦
                    </text>
                    {item.isResting && (
                      <text x={item.x} y={item.y + radius + 25} textAnchor="middle" fontSize="8.5" fill={colors.textFaint} fontFamily="'Work Sans', sans-serif" style={{ paintOrder: 'stroke', stroke: colors.bg, strokeWidth: 3 }}>
                        resting — {fmtRestRemaining(item.restRemainingMs)}
                      </text>
                    )}
                  </g>
                </g>
              );
            })}
            {showEnding && (
              <g>
                <Sparkles x={PATH_WIDTH / 2 - 8} y={y - DIVIDER_HEIGHT + 4} size={16} color={colors.gold} />
                <text x={PATH_WIDTH / 2} y={y - DIVIDER_HEIGHT + 40} textAnchor="middle" fontSize="11" fill={colors.text} fontFamily="'Work Sans', sans-serif" style={{ paintOrder: 'stroke', stroke: colors.bg, strokeWidth: 3 }}>{campaign.endingLabel}</text>
              </g>
            )}
          </svg>
        )}
      </div>

      {restingItem && positioned.some((p) => p.id === restingItem.id) ? (
        <div className="vf-body" style={{ fontSize: 11.5, color: colors.textFaint, textAlign: 'center', marginTop: 8 }}>
          Your body needs recovery before the next challenge — {fmtRestRemaining(restingItem.remainingMs)} remaining.
        </div>
      ) : (
        <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint, textAlign: 'center', marginTop: 8 }}>
          {canGoPrev || canGoNext ? 'Browsing a past Act — use the arrows to move between unlocked regions.' : 'The path follows your progress — tap the next glowing node to continue.'}
        </div>
      )}

      <div style={{ height: 78 }} />
      <div style={{ position: 'fixed', bottom: 0, left: '50%', transform: 'translateX(-50%)', width: '100%', maxWidth: 560, padding: '10px 14px calc(10px + env(safe-area-inset-bottom))', background: 'linear-gradient(180deg, rgba(22,20,18,0.9), rgba(13,12,10,0.98))', backdropFilter: 'blur(10px)', WebkitBackdropFilter: 'blur(10px)', borderTop: `1px solid ${colors.border}`, boxShadow: '0 -6px 20px rgba(0,0,0,0.35)', zIndex: 40, display: 'flex', justifyContent: 'space-around', gap: 8 }}>
        {[
          { icon: User, key: 'character', label: 'Character' },
          { icon: Users, key: 'party', label: 'Party', showDot: partyGoalMet(xp, partyMembers) },
          { icon: Backpack, key: 'inventory', label: 'Inventory' },
          { icon: SettingsIcon, key: 'settings', label: 'Settings' },
        ].map(({ icon: Icon, key, label, showDot }) => (
          <button key={key} onClick={() => { onOpenModal(key); sfx.tap(); }} aria-label={`Open ${label}`} className="vf-press"
            style={{ borderRadius: 14, position: 'relative', flex: 1, maxWidth: 90, padding: '9px 4px 7px', background: colors.panel, border: `1px solid ${colors.borderSoft}`, boxShadow: '0 2px 6px rgba(0,0,0,0.25)', cursor: 'pointer', display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3 }}>
            <Icon size={21} color={colors.gold} aria-hidden="true" />
            <span className="vf-body" style={{ fontSize: 10, color: colors.textMuted, fontWeight: 500 }}>{label}</span>
            {showDot && <span style={{ position: 'absolute', top: 5, right: '22%', width: 8, height: 8, borderRadius: '50%', background: colors.ember, border: `1.5px solid ${colors.panel}` }} />}
          </button>
        ))}
      </div>
    </div>
  );
}

/* ============================= APP ============================= */

function MainMenuScreen({ onSelectCampaign, profile, onOpenAuth }) {
  const [summaries, setSummaries] = useState({}); // id -> { xp, level } | 'new' | 'loading'
  const [expandedId, setExpandedId] = useState(null); // which campaign card is open, if any

  useEffect(() => {
    let cancelled = false;
    (async () => {
      for (const c of CAMPAIGNS) {
        try {
          const result = await localSave.get(`progress-${c.id}`);
          if (cancelled) return;
          if (result && result.value) {
            const s = JSON.parse(result.value);
            const totalXP = c.acts.flatMap((a) => a.chapters).flatMap((ch) => ch.quests).filter((q) => s.done && s.done[q.id]).reduce((sum, q) => sum + q.xp, 0);
            setSummaries((prev) => ({ ...prev, [c.id]: { xp: totalXP, level: levelFromXP(totalXP), characterName: s.characterName || null } }));
          } else {
            setSummaries((prev) => ({ ...prev, [c.id]: 'new' }));
          }
        } catch (e) {
          setSummaries((prev) => ({ ...prev, [c.id]: 'new' }));
        }
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return (
    <div style={{ position: 'relative', margin: '-22px', padding: 22, minHeight: '100%', textAlign: 'center' }}>
      {/* Full-bleed fog background — degrades to the standard app background (already set on the shell) when no art is generated yet */}
      {MENU_BG_FOG && (
        <>
          <img src={MENU_BG_FOG} alt="" aria-hidden="true" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover', zIndex: 0 }} />
          <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(rgba(13,12,10,0.55), rgba(13,12,10,0.92) 70%)', zIndex: 0 }} />
        </>
      )}
      <div style={{ position: 'relative', zIndex: 1, paddingTop: 36 }}>
        <button onClick={profile ? undefined : onOpenAuth} className="vf-body" style={{ borderRadius: 999, position: 'absolute', top: 0, right: 0, background: 'rgba(13,12,10,0.5)', border: `1px solid ${colors.border}`, color: colors.text, fontSize: 11, padding: '5px 10px', cursor: profile ? 'default' : 'pointer', display: 'flex', alignItems: 'center', gap: 5 }}>
          <User size={11} color={colors.gold} /> {profile ? profile.username : 'Sign In'}
        </button>
        <img src={MENU_LOGO} alt="Virelia" style={{ maxWidth: 220, width: '80%', height: 'auto', margin: '0 auto 6px', display: 'block', filter: 'drop-shadow(0 4px 12px rgba(0,0,0,0.5))' }} />
        <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint, marginBottom: 22, textShadow: MENU_BG_FOG ? '0 1px 6px rgba(0,0,0,0.8)' : 'none' }}>Choose your journey</div>

        {CAMPAIGNS.map((c) => {
          const summary = summaries[c.id];
          const Icon = c.icon;
          const isOpen = expandedId === c.id;
          const hasSave = summary && summary !== 'new' && summary !== 'loading';
          return (
            <div key={c.id} className="vf-press" style={{ borderRadius: 16, textAlign: 'left', marginBottom: 12, background: colors.panel, border: `1px solid ${colors.border}`, boxShadow: '0 8px 24px rgba(0,0,0,0.28)', overflow: 'hidden', cursor: 'pointer' }}>
              <div onClick={() => setExpandedId(isOpen ? null : c.id)} role="button" tabIndex={0} aria-expanded={isOpen} aria-label={`${c.name}, ${isOpen ? 'collapse' : 'expand'} details`}
                onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); setExpandedId(isOpen ? null : c.id); } }}
                style={{ position: 'relative', padding: 16, minHeight: c.cardArt ? 120 : 'auto' }}>
                {c.cardArt && (
                  <>
                    <img src={c.cardArt} alt="" aria-hidden="true" style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', objectFit: 'cover' }} />
                    <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(rgba(13,12,10,0.15), rgba(13,12,10,0.9))' }} />
                  </>
                )}
                <div style={{ position: 'relative' }}>
                  <div className="flex items-center justify-between" style={{ marginBottom: 4 }}>
                    <span className="flex items-center" style={{ gap: 8 }}>
                      <Icon size={18} color={colors.gold} />
                      <span className="vf-display" style={{ fontSize: 18, color: colors.text, textShadow: c.cardArt ? '0 1px 5px rgba(0,0,0,0.85)' : 'none' }}>{c.name}</span>
                    </span>
                    <span style={{ borderRadius: 999, fontSize: 10, color: colors.gold, border: `1px solid ${colors.gold}`, padding: '2px 8px', background: c.cardArt ? 'rgba(13,12,10,0.5)' : 'transparent' }}>{c.tone}</span>
                  </div>
                  <p style={{ fontSize: 12.5, color: colors.textMuted, lineHeight: 1.5, marginBottom: 8, textShadow: c.cardArt ? '0 1px 5px rgba(0,0,0,0.85)' : 'none' }}>{c.tagline}</p>
                  <div style={{ fontSize: 11.5, color: colors.textFaint, textShadow: c.cardArt ? '0 1px 5px rgba(0,0,0,0.85)' : 'none' }}>
                    {!summary || summary === 'loading' ? 'Checking progress…' : summary === 'new' ? 'Not started' : `${summary.characterName || 'Unnamed'} — Level ${summary.level}, ${summary.xp} XP`}
                  </div>
                </div>
              </div>
              {/* Expanded detail panel — a real accordion drop-down, not a fixed-height reveal, so it never clips content of varying length */}
              <div style={{ display: 'grid', gridTemplateRows: isOpen ? '1fr' : '0fr', transition: 'grid-template-rows 0.25s ease' }}>
                <div style={{ overflow: 'hidden' }}>
                  <div style={{ padding: '4px 16px 16px' }}>
                    <div style={{ borderTop: `1px solid ${colors.border}`, paddingTop: 12, marginBottom: 12 }}>
                      {hasSave ? (
                        <div className="flex items-center" style={{ gap: 10 }}>
                          <div style={{ borderRadius: 999, width: 38, height: 38, background: colors.panelAlt, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <User size={18} color={colors.gold} />
                          </div>
                          <div>
                            <div className="vf-body" style={{ fontSize: 13, color: colors.text }}>{summary.characterName || 'Unnamed'}</div>
                            <div className="vf-body" style={{ fontSize: 11, color: colors.textFaint }}>Level {summary.level} · {summary.xp} XP earned</div>
                          </div>
                        </div>
                      ) : (
                        <p className="vf-body" style={{ fontSize: 12, color: colors.textFaint, lineHeight: 1.5 }}>
                          No character yet — {c.protagonistTerm} awaits. Starting fresh builds your stats from real fitness tests.
                        </p>
                      )}
                    </div>
                    <button onClick={(e) => { e.stopPropagation(); onSelectCampaign(c.id); }} className="vf-body vf-press"
                      style={{ borderRadius: 12, width: '100%', padding: '11px 0', background: 'linear-gradient(135deg, #D65A34, #A83A1C)', boxShadow: '0 4px 14px rgba(189,74,38,0.35)', color: colors.text, border: 'none', fontSize: 13.5, fontWeight: 500, cursor: 'pointer' }}>
                      {hasSave ? 'Continue Journey' : 'Begin Journey'}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          );
        })}
        <p className="vf-body" style={{ fontSize: 11, color: colors.textFaint, marginTop: 4, textShadow: MENU_BG_FOG ? '0 1px 6px rgba(0,0,0,0.8)' : 'none' }}>
          Each campaign keeps its own save — stats, quests, and party are entirely separate between them.
        </p>
      </div>
    </div>
  );
}

export default function App() {
  const [modal, setModal] = useState(null); // null | 'character' | 'party' | 'inventory' | 'settings' | {type:'quest', quest, chapterTitle}
  const [activeCampaignId, setActiveCampaignId] = useState(null); // null = Main Menu
  const activeCampaign = CAMPAIGNS.find((c) => c.id === activeCampaignId) || null;

  // Account-level (shared across every campaign) — a physical fact about the player, not story progress.
  const [sex, setSex] = useState('male');
  const [age, setAge] = useState(30);
  const [units, setUnits] = useState('imperial');
  const [seenMenuTip, setSeenMenuTip] = useState(false);
  const [seenCharacterTip, setSeenCharacterTip] = useState(false);
  const [seenQuestTip, setSeenQuestTip] = useState(false);
  const [seenTrialsTip, setSeenTrialsTip] = useState(false);
  const [accountLoaded, setAccountLoaded] = useState(false);
  const [soundOn, setSoundOnState] = useState(true);
  const setSoundOn = (v) => { setSoundOnState(v); setSoundEnabled(v); };

  // Per-campaign state — fully reset and independently loaded/saved whenever activeCampaignId changes.
  const [raw, setRaw] = useState({});
  const [done, setDone] = useState({});
  const [statHistory, setStatHistory] = useState([]);
  const [committedScores, setCommittedScores] = useState({ STR: 10, CON: 10, DEX: 10, FLX: 10 });
  const [committedRaw, setCommittedRaw] = useState({});
  const [chosenClass, setChosenClass] = useState(null);
  const [started, setStarted] = useState(false);
  const [creating, setCreating] = useState(false); // between Welcome and actually starting: the character creator
  const [characterName, setCharacterName] = useState('');
  const [avatarBuild, setAvatarBuild] = useState('balanced');
  const [avatarAccent, setAvatarAccent] = useState('ember');
  const [avatarAccessory, setAvatarAccessory] = useState('none');
  const [paywallUnlocked, setPaywallUnlocked] = useState(false);
  const [partyRoomCode, setPartyRoomCode] = useState(null); // null = not in a party
  const [myPartyMemberId, setMyPartyMemberId] = useState(null); // my own row id in party_members, for updates
  const [partyMembers, setPartyMembers] = useState([]); // other members, always freshly fetched — never persisted locally
  const [partyLoading, setPartyLoading] = useState(false);
  const [partyError, setPartyError] = useState(null);
  const [campaignLoaded, setCampaignLoaded] = useState(false);
  const [session, setSession] = useState(null); // null = not logged in, playing on local saves only
  const [profile, setProfile] = useState(null); // { id, username } once logged in
  const [sessionChecked, setSessionChecked] = useState(false); // avoids a "Sign In" flash before the real session loads

  // Picks up an existing session on load, and any future sign-in/sign-out (including the redirect
  // back from Google) — this is the one source of truth for whether the player has an account.
  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => { setSession(data.session); setSessionChecked(true); });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, newSession) => setSession(newSession));
    return () => listener.subscription.unsubscribe();
  }, []);

  // Load (or lazily create) the profile row once a session exists — covers the Google sign-in
  // case too, where there's no separate "create profile" step the way email sign-up has one.
  useEffect(() => {
    if (!session) { setProfile(null); return; }
    (async () => {
      const { data, error } = await supabase.from('profiles').select('id, username').eq('id', session.user.id).maybeSingle();
      if (error) console.error('Profile load failed:', error.message, error);
      if (data) {
        setProfile(data);
      } else {
        const fallbackName = (session.user.email || 'Player').split('@')[0];
        const { data: created, error: createError } = await supabase.from('profiles').insert({ id: session.user.id, username: fallbackName }).select().maybeSingle();
        if (createError) console.error('Profile creation failed:', createError.message, createError);
        if (created) setProfile(created);
      }
    })();
  }, [session]);

  const ACCOUNT_KEY = 'account-v1';

  // Load account data once, on first mount, regardless of which campaign gets picked.
  useEffect(() => {
    (async () => {
      try {
        const result = await localSave.get(ACCOUNT_KEY);
        if (result && result.value) {
          const s = JSON.parse(result.value);
          if (s.sex) setSex(s.sex);
          if (s.age) setAge(s.age);
          if (s.units) setUnits(s.units);
          if (s.soundOn === false) setSoundOn(false); // default stays true unless explicitly turned off
          if (s.seenMenuTip) setSeenMenuTip(true);
          if (s.seenCharacterTip) setSeenCharacterTip(true);
          if (s.seenQuestTip) setSeenQuestTip(true);
          if (s.seenTrialsTip) setSeenTrialsTip(true);
        }
      } catch (e) {
        // No account save yet — proceed with defaults.
      }
      setAccountLoaded(true);
    })();
  }, []);

  useEffect(() => {
    if (!accountLoaded) return;
    const snapshot = { sex, age, units, soundOn, seenMenuTip, seenCharacterTip, seenQuestTip, seenTrialsTip };
    localSave.set(ACCOUNT_KEY, JSON.stringify(snapshot)).catch(() => {});
  }, [accountLoaded, sex, age, units, soundOn, seenMenuTip, seenCharacterTip, seenQuestTip, seenTrialsTip]);

  // Entering a campaign: reset in-memory state to safe defaults FIRST, then attempt to load that
  // campaign's own save. This ordering matters — without it, a leftover save-effect tick could
  // write one campaign's state under another campaign's key during the switch.
  // Logged in: saves live in Supabase, tied to the account, so they follow the player across
  // devices. Logged out: same localStorage fallback as before — playing without an account has
  // never required one and still doesn't.
  const applySnapshot = (s) => {
    if (s.done) setDone(s.done);
    if (s.statHistory) setStatHistory(s.statHistory);
    if (s.committedScores) setCommittedScores(s.committedScores);
    if (s.committedRaw) setCommittedRaw(s.committedRaw);
    if (s.chosenClass !== undefined) setChosenClass(s.chosenClass);
    if (s.paywallUnlocked) setPaywallUnlocked(s.paywallUnlocked);
    if (s.partyRoomCode) setPartyRoomCode(s.partyRoomCode);
    if (s.myPartyMemberId) setMyPartyMemberId(s.myPartyMemberId);
    if (s.characterName) setCharacterName(s.characterName);
    if (s.avatarBuild) setAvatarBuild(s.avatarBuild);
    if (s.avatarAccent) setAvatarAccent(s.avatarAccent);
    if (s.avatarAccessory) setAvatarAccessory(s.avatarAccessory);
  };
  const selectCampaign = async (id) => {
    setCampaignLoaded(false);
    setDone({}); setRaw({}); setStatHistory([]); setCommittedScores({ STR: 10, CON: 10, DEX: 10, FLX: 10 });
    setCommittedRaw({}); setChosenClass(null); setPaywallUnlocked(false);
    setPartyRoomCode(null); setMyPartyMemberId(null); setPartyMembers([]); setPartyError(null);
    setStarted(false); setCreating(false);
    setCharacterName(''); setAvatarBuild('balanced'); setAvatarAccent('ember'); setAvatarAccessory('none');
    setActiveCampaignId(id);
    try {
      if (session) {
        const { data, error } = await supabase.from('saves').select('data').eq('user_id', session.user.id).eq('campaign_id', id).maybeSingle();
        if (error) console.error('Cloud save load failed:', error.message, error);
        if (data) {
          applySnapshot(data.data);
          setStarted(true);
        } else {
          // No cloud save yet for this account — check for local progress from before signing
          // in and adopt it as a one-time upload, rather than silently discarding it.
          const local = await localSave.get(`progress-${id}`);
          if (local && local.value) {
            const s = JSON.parse(local.value);
            applySnapshot(s);
            setStarted(true);
            const { error: migrateError } = await supabase.from('saves').insert({ user_id: session.user.id, campaign_id: id, data: s });
            if (migrateError) console.error('Local-to-cloud save migration failed:', migrateError.message, migrateError);
          }
        }
      } else {
        const result = await localSave.get(`progress-${id}`);
        if (result && result.value) {
          applySnapshot(JSON.parse(result.value));
          setStarted(true); // returning players skip the fresh-start Welcome/Creator flow for THIS campaign
        }
      }
    } catch (e) {
      // No save for this campaign yet — proceed as a first-time player of it.
    }
    setCampaignLoaded(true);
  };

  const returnToMenu = () => { setModal(null); setActiveCampaignId(null); };

  // If someone signs in (or out) while already mid-campaign — not from the Main Menu, where
  // selectCampaign already handles this — re-resolve which save is authoritative instead of
  // letting the save-effect below blindly push whatever's in memory over a real cloud save.
  const prevSessionRef = useRef(session);
  useEffect(() => {
    const sessionChanged = (prevSessionRef.current?.user?.id || null) !== (session?.user?.id || null);
    prevSessionRef.current = session;
    if (sessionChanged && activeCampaignId && campaignLoaded) selectCampaign(activeCampaignId);
  }, [session]);

  useEffect(() => {
    if (!campaignLoaded || !activeCampaignId) return;
    const snapshot = { done, statHistory, committedScores, committedRaw, chosenClass, paywallUnlocked, partyRoomCode, myPartyMemberId, started, characterName, avatarBuild, avatarAccent, avatarAccessory };
    if (session) {
      supabase.from('saves').upsert({ user_id: session.user.id, campaign_id: activeCampaignId, data: snapshot, updated_at: new Date().toISOString() }).then(({ error }) => {
        if (error) console.error('Cloud save failed:', error.message, error);
      });
    } else {
      localSave.set(`progress-${activeCampaignId}`, JSON.stringify(snapshot)).catch(() => {});
    }
  }, [campaignLoaded, activeCampaignId, session, done, statHistory, committedScores, committedRaw, chosenClass, paywallUnlocked, partyRoomCode, myPartyMemberId, started, characterName, avatarBuild, avatarAccent, avatarAccessory]);


  // Live preview of what the current draft input would produce — shown inside Character's Trials
  // form (per-field percentile bars, score, modifier) so typing gives immediate feedback, but this
  // never leaks out to quest scaling or class recommendation on its own.
  const draftScores = useMemo(() => {
    const out = {};
    for (const def of STAT_DEFS) {
      const pcts = def.tests.map((t) => {
        const v = raw[t]; if (v === '' || v === undefined) return null;
        return percentileFor(toMetricValue(t, v, units), ageBandStats(sex, age, NORMS[t]), NORMS[t].direction);
      }).filter((p) => p !== null);
      out[def.key] = pcts.length ? stat_score(pcts.reduce((a, b) => a + b, 0) / pcts.length) : 10;
    }
    return out;
  }, [raw, sex, age, units]);

  const mods = useMemo(() => ({ STR: modifier(committedScores.STR), CON: modifier(committedScores.CON), DEX: modifier(committedScores.DEX), FLX: modifier(committedScores.FLX) }), [committedScores]);
  const rec = useMemo(() => recommendClass(committedScores), [committedScores]);
  const effectiveClassName = chosenClass || rec.name;

  const campaignQuests = () => {
    if (!activeCampaign) return [];
    const mainQuests = activeCampaign.acts.flatMap((a) => a.chapters).flatMap((c) => c.quests);
    // Branch quests are keyed per-class, but any variant that was ever actually completed needs
    // to stay findable by id regardless of the player's CURRENT class selection — so this
    // includes every class's variant, not just whichever one is active right now.
    const branchQuests = activeCampaign.acts.flatMap((a) => (a.branches || []).flatMap((b) => Object.values(b.questsByClass).flatMap((steps) => steps.map((step) => step.quest))));
    return [...mainQuests, ...branchQuests];
  };
  // XP bonuses depend on which perks are unlocked, which depends on Level, which depends on XP —
  // to avoid a circular calculation, perk lookups use the BASE (unbonused) level. Since every
  // bonus is additive and positive, this is stable (never oscillates), though it does mean a
  // bonus that would newly unlock a higher tier isn't applied within that same calculation pass —
  // a deliberate, documented simplification rather than an oversight.
  const baseTotalXP = useMemo(() => campaignQuests().filter((q) => done[q.id]).reduce((sum, q) => sum + q.xp, 0), [done, activeCampaignId]);
  const baseLevel = levelFromXP(baseTotalXP);
  const totalXP = useMemo(() => campaignQuests().filter((q) => done[q.id]).reduce((sum, q) => sum + xpWithPerkBonus(q.xp, q, effectiveClassName, baseLevel), 0), [done, activeCampaignId, effectiveClassName, baseLevel]);
  const level = levelFromXP(totalXP);

  // Real party backend calls (Section 19) — each of these hits Supabase directly, no mock data.
  const refreshParty = async (code, myId) => {
    const roomCode = code || partyRoomCode;
    const excludeId = myId !== undefined ? myId : myPartyMemberId;
    if (!roomCode) return;
    setPartyLoading(true); setPartyError(null);
    try {
      const rows = await supabaseFetch(`party_members?room_code=eq.${roomCode}&select=*&order=xp.desc`);
      setPartyMembers((rows || []).filter((r) => r.id !== excludeId));
    } catch (e) {
      setPartyError(`Could not reach the party server. ${e.message}`);
    }
    setPartyLoading(false);
  };
  // A logged-in player's party presence uses their real account username, since that's the
  // persistent identity now — it's what should carry over into Guilds later too, not a
  // per-campaign character name that could differ between Virelia and The Long Road.
  const partyDisplayName = () => (profile ? profile.username : characterName) || 'Unnamed';
  const createParty = async () => {
    setPartyLoading(true); setPartyError(null);
    try {
      const code = genRoomCode();
      await supabaseFetch('party_rooms', { method: 'POST', body: JSON.stringify({ code }) });
      const [myRow] = await supabaseFetch('party_members', {
        method: 'POST',
        body: JSON.stringify({ room_code: code, user_id: session ? session.user.id : null, character_name: partyDisplayName(), level, xp: totalXP, campaign_id: activeCampaignId }),
      });
      setPartyRoomCode(code);
      setMyPartyMemberId(myRow.id);
      setPartyMembers([]);
    } catch (e) {
      setPartyError(`Could not create a party. ${e.message}`);
    }
    setPartyLoading(false);
  };
  const joinParty = async (code) => {
    setPartyLoading(true); setPartyError(null);
    try {
      const rooms = await supabaseFetch(`party_rooms?code=eq.${code}&select=code`);
      if (!rooms || rooms.length === 0) {
        setPartyError('No party found with that code.');
        setPartyLoading(false);
        return;
      }
      const [myRow] = await supabaseFetch('party_members', {
        method: 'POST',
        body: JSON.stringify({ room_code: code, user_id: session ? session.user.id : null, character_name: partyDisplayName(), level, xp: totalXP, campaign_id: activeCampaignId }),
      });
      setPartyRoomCode(code);
      setMyPartyMemberId(myRow.id);
      await refreshParty(code, myRow.id);
    } catch (e) {
      setPartyError(`Could not join that party. ${e.message}`);
    }
    setPartyLoading(false);
  };
  const leaveParty = () => {
    setPartyRoomCode(null); setMyPartyMemberId(null); setPartyMembers([]); setPartyError(null);
  };
  // Reconnect to an already-saved party room once, right after a campaign finishes loading.
  useEffect(() => {
    if (campaignLoaded && partyRoomCode) refreshParty();
  }, [campaignLoaded, partyRoomCode]);
  // Keep my own row's stats current in the background whenever they actually change, so teammates
  // see real progress without either side needing to do anything — this is what makes it a genuine
  // shared goal instead of a snapshot from whenever someone last opened the Party modal.
  useEffect(() => {
    if (!partyRoomCode || !myPartyMemberId) return;
    supabaseFetch(`party_members?id=eq.${myPartyMemberId}`, {
      method: 'PATCH',
      body: JSON.stringify({ character_name: partyDisplayName(), level, xp: totalXP, updated_at: new Date().toISOString() }),
    }).catch((e) => console.error('Party stat sync failed:', e.message));
  }, [partyRoomCode, myPartyMemberId, level, totalXP, characterName, profile]);
  const nextTier = TIERS.find((t) => level < t.level);
  const xpForNext = nextTier ? xpForLevel(nextTier.level) : null;

  const completeQuest = (id) => {
    setDone((d) => ({ ...d, [id]: Date.now() }));
    const quest = campaignQuests().find((q) => q.id === id);
    if (quest && quest.type !== 'story') sfx.questComplete(); // story beats are frequent and 0-XP — a chime on every one would get noisy fast
    if (quest && quest.requiresTrials) {
      // This IS the retest: commit whatever's currently in the draft, record it in history,
      // then clear the draft so the next Trials-gated quest requires genuinely fresh entry —
      // stale leftover numbers can never silently satisfy a later boss fight.
      setCommittedScores(draftScores);
      setCommittedRaw(raw);
      setStatHistory((h) => [...h, { timestamp: Date.now(), label: quest.title, STR: draftScores.STR, CON: draftScores.CON, DEX: draftScores.DEX, FLX: draftScores.FLX }]);
      setRaw({});
    }
  };
  // Testing-only helper: wipes THIS campaign's progress back to a fresh start (account info untouched).
  const resetProgress = () => {
    setDone({}); setRaw({}); setCommittedScores({ STR: 10, CON: 10, DEX: 10, FLX: 10 }); setCommittedRaw({}); setChosenClass(null);
    setModal(null); setPaywallUnlocked(false); setStatHistory([]);
    setPartyRoomCode(null); setMyPartyMemberId(null); setPartyMembers([]); setPartyError(null);
    setStarted(false); setCreating(false);
    setCharacterName(''); setAvatarBuild('balanced'); setAvatarAccent('ember'); setAvatarAccessory('none');
    if (activeCampaignId) localSave.delete(`progress-${activeCampaignId}`).catch(() => {});
  };

  const openQuest = (id, chapterTitle) => {
    const quest = campaignQuests().find((q) => q.id === id);
    setModal({ type: 'quest', quest, chapterTitle });
  };

  return (
    <div style={{ width: '100%', minHeight: '100dvh', background: 'radial-gradient(ellipse at top, #1a1713 0%, #0D0C0A 65%)', display: 'flex', justifyContent: 'center', alignItems: 'flex-start' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Work+Sans:wght@400;500;600&display=swap');
        .vf-display { font-family: 'Fraunces', serif; } .vf-body { font-family: 'Work Sans', sans-serif; }
        .vf-press { transition: transform 0.12s ease, box-shadow 0.12s ease; }
        .vf-press:active { transform: scale(0.96); }
        @keyframes vfNodeIn { from { opacity: 0; transform: scale(0.4); } to { opacity: 1; transform: scale(1); } }
        @keyframes vfFadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }
        @keyframes vfModalIn { from { opacity: 0; transform: scale(0.94) translateY(8px); } to { opacity: 1; transform: scale(1) translateY(0); } }
        @keyframes vfBackdropIn { from { opacity: 0; } to { opacity: 1; } }
        .vf-modal-backdrop { animation: vfBackdropIn 0.18s ease-out; }
        .vf-modal-dialog { animation: vfModalIn 0.22s cubic-bezier(0.34, 1.56, 0.64, 1); }
        @keyframes vfPulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
        .vf-node-in { animation: vfNodeIn 0.35s cubic-bezier(0.34, 1.56, 0.64, 1); transform-origin: center; }
        .vf-fade-in { animation: vfFadeIn 0.3s ease-out; }
        .vf-pulse { animation: vfPulse 1.8s ease-in-out infinite; }
        @keyframes vfLevelUp { 0% { opacity: 0; transform: translate(-50%, -12px) scale(0.85); } 15% { opacity: 1; transform: translate(-50%, 0) scale(1.04); } 25% { transform: translate(-50%, 0) scale(1); } 85% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -6px) scale(0.98); } }
        .vf-level-up-toast { animation: vfLevelUp 3s cubic-bezier(0.34, 1.56, 0.64, 1) forwards; }
        /* Full-viewport app shell — the game fills the real screen edge-to-edge instead of
           floating as a bounded card, with its own internal scroll so fixed HUD elements
           (top status bar, bottom nav) can stay pinned to the actual screen edges. */
        .vf-app-shell { width: 100%; max-width: 560px; position: relative; padding: 22px; }
        .vf-app-shell::-webkit-scrollbar { display: none; }
      `}</style>
      <div className="vf-app-shell">
        {!accountLoaded ? (
          <div className="vf-fade-in" style={{ textAlign: 'center', paddingTop: 100 }}>
            <div className="vf-pulse" style={{ display: 'inline-flex', width: 56, height: 56, borderRadius: '50%', background: colors.panelAlt, border: `1px solid ${colors.border}`, alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              <VireliaSigilIcon size={26} color={colors.gold} />
            </div>
            <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint }}>Loading…</div>
          </div>
        ) : !sessionChecked ? (
          <div className="vf-fade-in" style={{ textAlign: 'center', paddingTop: 100 }}>
            <div className="vf-pulse" style={{ display: 'inline-flex', width: 56, height: 56, borderRadius: '50%', background: colors.panelAlt, border: `1px solid ${colors.border}`, alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              <VireliaSigilIcon size={26} color={colors.gold} />
            </div>
            <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint }}>Loading…</div>
          </div>
        ) : !activeCampaign ? (
          <MainMenuScreen onSelectCampaign={selectCampaign} profile={profile} onOpenAuth={() => setModal('auth')} />
        ) : !campaignLoaded ? (
          <div className="vf-fade-in" style={{ textAlign: 'center', paddingTop: 100 }}>
            <div className="vf-pulse" style={{ display: 'inline-flex', width: 56, height: 56, borderRadius: '50%', background: colors.panelAlt, border: `1px solid ${colors.border}`, alignItems: 'center', justifyContent: 'center', marginBottom: 14 }}>
              <VireliaSigilIcon size={26} color={colors.gold} />
            </div>
            <div className="vf-body" style={{ fontSize: 12, color: colors.textFaint }}>Loading…</div>
          </div>
        ) : started ? (
          <PathScreen campaign={activeCampaign} done={done} level={level} className={chosenClass || rec.name} xp={totalXP} mods={mods} onOpenQuest={openQuest} onOpenModal={setModal} seenMenuTip={seenMenuTip} onDismissMenuTip={() => setSeenMenuTip(true)} paywallUnlocked={paywallUnlocked} onUnlockPaywall={() => setPaywallUnlocked(true)} partyMembers={partyMembers} characterName={characterName} />
        ) : creating ? (
          <CharacterCreatorScreen campaign={activeCampaign} name={characterName} setName={setCharacterName} build={avatarBuild} setBuild={setAvatarBuild} accent={avatarAccent} setAccent={setAvatarAccent} accessory={avatarAccessory} setAccessory={setAvatarAccessory} onConfirm={() => setStarted(true)} />
        ) : (
          <WelcomeScreen campaignName={activeCampaign.name} onStart={() => setCreating(true)} />
        )}
      </div>

      {modal === 'character' && (
        <Modal title="Your Character" onClose={() => setModal(null)}>
          <CharacterModal sex={sex} age={age} units={units} committedRaw={committedRaw} committedScores={committedScores} chosenClass={chosenClass} setChosenClass={setChosenClass} rec={rec} level={level} xp={totalXP} nextTier={nextTier} xpForNext={xpForNext} statHistory={statHistory} characterName={characterName} avatarBuild={avatarBuild} avatarAccent={avatarAccent} avatarAccessory={avatarAccessory} campaign={activeCampaign} done={done} />
        </Modal>
      )}
      {modal === 'party' && <Modal title="Party" onClose={() => setModal(null)}><PartyModal myXP={totalXP} myLevel={level} characterName={characterName} roomCode={partyRoomCode} members={partyMembers} loading={partyLoading} error={partyError} onCreateRoom={createParty} onJoinRoom={joinParty} onRefresh={() => refreshParty()} onLeaveRoom={leaveParty} /></Modal>}
      {modal === 'auth' && <Modal title="Account" onClose={() => setModal(null)}><AuthModal onClose={() => setModal(null)} /></Modal>}
      {modal === 'inventory' && activeCampaign && <Modal title="Inventory" onClose={() => setModal(null)}><InventoryModal campaign={activeCampaign} done={done} /></Modal>}
      {modal === 'settings' && <Modal title="Settings" onClose={() => setModal(null)}><SettingsModal sex={sex} setSex={setSex} age={age} setAge={setAge} units={units} setUnits={setUnits} soundOn={soundOn} setSoundOn={setSoundOn} onResetProgress={resetProgress} onSwitchCampaign={returnToMenu} campaignName={activeCampaign ? activeCampaign.name : null} characterName={characterName} setCharacterName={setCharacterName} avatarBuild={avatarBuild} setAvatarBuild={setAvatarBuild} avatarAccent={avatarAccent} setAvatarAccent={setAvatarAccent} avatarAccessory={avatarAccessory} setAvatarAccessory={setAvatarAccessory} profile={profile} onOpenAuth={() => setModal('auth')} onSignOut={() => supabase.auth.signOut()} /></Modal>}
      {modal && modal.type === 'quest' && (
        <Modal title={modal.quest.title} onClose={() => setModal(null)}>
          <QuestModal quest={modal.quest} chapterTitle={modal.chapterTitle} done={done} onComplete={(id) => { completeQuest(id); setModal(null); }} mods={mods} raw={raw} setRaw={setRaw} sex={sex} age={age} units={units} onOpenModal={setModal} seenQuestTip={seenQuestTip} onDismissQuestTip={() => setSeenQuestTip(true)} seenTrialsTip={seenTrialsTip} onDismissTrialsTip={() => setSeenTrialsTip(true)} />
        </Modal>
      )}
    </div>
  );
}
